INSERT INTO `cloned_files` (`path`,`content`,`size`,`mime`) VALUES ('css/styles_502b90.css',':root {\n  --font-geist-sans: Arial, Helvetica, sans-serif;\n  --font-geist-mono: "SFMono-Regular", Consolas, "Liberation Mono", monospace;\n  --ink: #171714;\n  --paper: #f2eee5;\n  --cream: #fbf8f1;\n  --muted: #77736b;\n  --coral: #ff5a36;\n  --gold: #dcb45b;\n  --acid: #e7ff53;\n  --line: rgba(23,23,20,.16);\n}\n\n* { box-sizing: border-box; }\nhtml { width: 100%; max-width: 100%; scroll-behavior: smooth; }\nbody { width: 100%; max-width: 100%; margin: 0; overflow-x: clip; background: var(--paper); color: var(--ink); font-family: var(--font-geist-sans), Arial, sans-serif; }\nmain, section, footer { min-width: 0; }\nimg { max-width: 100%; }\na { color: inherit; text-decoration: none; }\nbutton, input { font: inherit; }\nbutton { color: inherit; }\n.page-shell { width: min(1240px, calc(100% - 48px)); margin: 0 auto; }\n.nav-wrap { width: min(1380px, calc(100% - 24px)); margin: 0 auto; }\n\nbody::before {\n  content: ""; position: fixed; inset: 0; z-index: -1; pointer-events: none; opacity: .22;\n  background-image: radial-gradient(rgba(23,23,20,.5) .55px, transparent .7px); background-size: 10px 10px;\n  mask-image: linear-gradient(#000, transparent 72%);\n}\n\n.nav-wrap { height: 88px; display: flex; align-items: center; gap: 44px; position: sticky; top: 0; z-index: 100; border-bottom: 1px solid var(--line); background: rgba(242,238,229,.94); box-shadow: 0 8px 22px rgba(23,23,20,.07); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); }\n.brand { display: inline-flex; align-items: center; gap: 12px; font-size: 21px; font-weight: 950; letter-spacing: -1.4px; white-space: nowrap; }\n.brand-logo { width: 176px; height: auto; display: block; object-fit: contain; }\n.brand-logo-large { width: 220px; height: auto; }\nnav { margin-left: auto; display: flex; gap: 34px; }\nnav a { font-size: 12px; font-weight: 720; }\nnav a::before { content: "↳ "; color: var(--cora