 11px; padding-left: 19px; color: #d8d4ca; font-size: 11px; font-weight: 750; line-height: 1.5; text-transform: uppercase; }\n.activity-copy-card li::before { content: "◆"; position: absolute; left: 0; top: 1px; color: var(--coral); font-size: 8px; }\n.activity-accent { background: var(--coral); color: #fff; border-color: var(--coral); box-shadow: 7px 7px 0 var(--acid); }\n.activity-accent .activity-index { color: var(--ink); }\n.activity-accent p, .activity-accent li { color: #fff; }\n.activity-accent li::before { color: var(--acid); }\n.telegram-inline { position: absolute; left: 28px; bottom: 27px; min-height: 43px; padding: 0 15px; display: inline-flex; align-items: center; gap: 9px; background: #229ed9; color: #fff; font-size: 9px; font-weight: 900; letter-spacing: .4px; text-transform: uppercase; transition: .2s; }\n.telegram-inline:hover { transform: translateY(-2px); background: var(--acid); color: var(--ink); }\n.telegram-inline svg { width: 18px; height: 18px; fill: currentColor; }\n.telegram-inline span { margin-left: 8px; }\n.activity-table-card { padding-bottom: 20px; background: var(--cream); color: var(--ink); }\n.table-scroll { overflow-x: auto; outline: none; }\n.activity-table-card table { width: 100%; border-collapse: collapse; font-size: 10px; text-align: center; }\n.activity-table-card th { padding: 12px 8px; background: var(--coral); color: #fff; font-size: 8px; letter-spacing: .25px; text-transform: uppercase; }\n.activity-table-card th + th { border-left: 1px solid rgba(255,255,255,.45); }\n.activity-table-card td { padding: 10px 8px; border: 1px solid #d5cec1; }\n.activity-table-card tbody tr:nth-child(even) { background: #eee8dc; }\n.activity-table-card tbody tr:hover { background: var(--acid); }\n\n.telegram-float { position: fixed; right: 24px; bottom: 24px; z-index: 80; height: 54px; padding: 0 20px 0 15px; display: flex; align-items: center; gap: 10px; border: 2px solid rgba(255,255,255,.85); border-radius: 99px; background: #229ed9; co