n\n\nfooter { background: var(--ink); color: var(--cream); }\n.footer-inner { min-height: 110px; display: flex; align-items: center; justify-content: space-between; }\n.footer-inner p, .footer-inner > a:last-child { color: #77746d; font-size: 10px; }\n\n@media (max-width: 1050px) {\n  .nav-wrap { height: 76px; gap: 12px; }\n  .menu-toggle { display: grid; place-items: center; margin-left: auto; width: 40px; height: 40px; flex: 0 0 auto; border: 1px solid var(--ink); border-radius: 50%; background: transparent; cursor: pointer; }\n  nav { display: none; position: absolute; top: calc(100% - 4px); left: 0; right: 0; margin: 0; padding: 18px; background: var(--cream); border: 1px solid var(--ink); box-shadow: 7px 7px 0 var(--ink); }\n  nav.open { display: grid; gap: 16px; }\n  .hero-grid { grid-template-columns: 1fr; }\n  .hero h1 { font-size: 72px; letter-spacing: -6px; }\n  .hero-art { min-height: 610px; }\n  .hero-art::before { inset: 20px 0 34px; }\n  .hero-art > img { inset: 14px 0 20px; width: 100%; height: calc(100% - 34px); object-position: 15% bottom; }\n  .game-card { flex-basis: 185px; }\n  .access-section { gap: 45px; }\n}\n\n@media (max-width: 760px) {\n  .page-shell, .nav-wrap { width: calc(100% - 24px); }\n  .nav-wrap { height: 70px; gap: 10px; }\n  .brand { font-size: 18px; }\n  .brand-logo { width: 152px; height: auto; }\n  .menu-toggle { width: 38px; height: 38px; }\n  nav { padding: 17px; }\n  .nav-cta { min-height: 39px; padding: 0 11px; font-size: 8px; }\n  .nav-cta span { margin-left: 6px; }\n  .hero { width: calc(100% - 12px); margin-top: 6px; }\n  .hero-grid { width: calc(100% - 24px); min-height: 845px; grid-template-columns: 1fr; }\n  .hero-copy { padding: 60px 4px 15px; }\n  .hero h1 { font-size: 55px; line-height: .86; letter-spacing: -4px; margin-top: 25px; }\n  .hero h1 em { letter-spacing: -3px; }\n  .hero-lead { max-width: 95%; font-size: 13px; line-height: 1.6; }\n  .hero-actions { margin-top: 25px; gap: 15px; }\n  .primary-button { min-height: 47px; padding: 0 15px; gap: 17px; font-size: 9px; }\n  .text-button { font-size: 10px; }\n  .hero-stats { margin-top: 37px; }\n  .hero-stats div { flex: 1; min-width: 0; margin-right: 11px; padding-right: 11px; }\n  .hero-stats strong { font-size: 18px; }\n  .hero-stats small { font-size: 7px; }\n  .hero-verify { grid-template-columns: 1fr auto; }\n  .hero-verify .verify-intro { grid-column: 1 / -1; }\n  .hero-access-panel .route-grid { grid-template-columns: repeat(2,minmax(0,1fr)); }\n  .hero-art { min-height: 560px; }\n  .hero-art::before { inset: 15px -12px 13px 25px; }\n  .hero-art::after { right: -76px; top: 125px; font-size: 46px; }\n  .hero-art > img { inset: 10px 0 12px; width: 100%; height: calc(100% - 22px); object-fit: contain; object-position: left bottom; }\n  .ring-one { width: 300px; height: 300px; top: 43px; left: 36px; }\n  .ring-two { width: 345px; height: 345px; top: 20px; left: 13px; }\n  .jackpot-card { width: 235px; min-height: 70px; right: 2px; bottom: 11px; }\n  .jackpot-card strong { font-size: 12px; }\n  .ticker { height: 40px; }\n  .ticker > span { padding: 0 14px; font-size: 7px; }\n  .ticker p { padding-left: 17px; font-size: 7px; }\n  .access-section { grid-template-columns: 1fr; gap: 30px; padding: 78px 0; }\n  .section-intro { padding-top: 0; }\n  .section-intro h2, .games-heading h2, .support-copy h2 { font-size: 45px; letter-spacing: -3px; }\n  .access-panel { box-shadow: 7px 7px 0 var(--ink); }\n  .route-grid { grid-template-columns: 1fr; }\n  .route-grid > a { border-right: 0; }\n  .verify-box { grid-template-columns: 1fr auto; }\n  .verify-intro { grid-column: 1 / -1; }\n  .games-section { padding: 78px 0; }\n  .games-heading { align-items: start; }\n  .game-grid { --game-gap: 10px; animation-duration: 30s; }\n  .game-card { flex-basis: 148px; }\n  .game-card { padding: 5px; }\n  .benefits { grid-template-columns: 1fr; margin-top: 62px; }\n  .benefits article { min-height: 120px; border-right: 0; border-bottom: 1px solid var(--ink); }\n  .agent-activity { margin-top: 75px; padding: 78px 0; }\n  .activity-heading { grid-template-columns: 1fr; gap: 24px; margin-bottom: 32px; }\n  .activity-heading h2 { font-size: 45px; letter-spacing: -3px; }\n  .activity-heading > p { max-width: 95%; }\n  .activity-grid { grid-template-columns: 1fr; }\n  .activity-card { padding: 22px; box-shadow: 5px 5px 0 rgba(255,90,54,.28); }\n  .activity-accent { box-shadow: 5px 5px 0 var(--acid); }\n  .activity-card h3 { font-size: 21px; }\n  .activity-copy-card { min-height: 300px; }\n  .telegram-inline { left: 22px; bottom: 22px; }\n  .activity-table-card { padding: 22px 12px 14px; }\n  .activity-table-card h3, .activity-table-card .activity-index { margin-left: 10px; }\n  .activity-table-card table { min-width: 0; table-layout: fixed; }\n  .activity-table-card th, .activity-table-card td { padding: 9px 4px; overflow-wrap: anywhere; }\n  .telegram-float { right: 14px; bottom: 14px; width: 54px; padding: 0; justify-content: center; }\n  .telegram-float span { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }\n  .support-section { grid-template-columns: 1fr; gap: 45px; padding: 85px 0; }\n  .footer-inner { min-height: 135px; flex-wrap: wrap; gap: 10px; padding: 27px 0; }\n  .footer-inner p { order: 3; width: 100%; }\n}\n\n/* ===== v42 responsive layout cleanup =====\n   Keep the desktop content on one aligned grid and give the phone hero\n   enough width/height for the mascot artwork to remain readable. */\n@media (min-width: 761px) {\n  .nav-wrap,\n  .hero,\n  .games-section .page-shell,\n  .benefits,\n  .agent-activity .page-shell,\n  .support-section,\n  .platform-details-inner,\n  footer .page-shell {\n    width: min(1240px, calc(100% - 48px));\n  }\n\n  .nav-wrap { margin-top: 18px; }\n  .hero-grid {\n    width: min(1180px, calc(100% - 64px));\n    min-height: 650px;\n    grid-template-columns: minmax(0, 1fr) minmax(420px, .92fr);\n    gap: 28px;\n  }\n  .hero-copy { padding: 54px 0 32px; }\n  .hero-art { min-height: 650px; }\n  .hero-art > img {\n    inset: auto 0 0 auto;\n    width: 112%;\n    height: 100%;\n    object-fit: contain;\n    object-position: center bottom;\n  }\n\n  .games-section { padding: 58px 0 54px; }\n  .games-heading { margin-bottom: 28px; }\n  .benefits { margin-top: 24px; }\n  .agent-activity { margin-top: 34px; padding: 64px 0 66px; }\n  .activity-heading { margin-bottom: 34px; }\n  .support-section { padding: 70px 0; gap: 60px; }\n  .platform-details { padding: 42px 24px 34px; }\n}\n\n@media (max-width: 760px) {\n  .hero-grid {\n    width: 100%;\n    padding: 0 12px 18px;\n    display: grid;\n    grid-template-columns: minmax(0, 1fr);\n    grid-template-areas:\n      "intro"\n      "verify"\n      "access"\n      "actions"\n      "stats"\n      "art";\n    gap: 0;\n  }\n  .hero-intro { padding: 24px 6px 16px; }\n  .hero h1 { font-size: clamp(42px, 13vw, 58px); letter-spacing: -3.4px; }\n  .hero-lead { max-width: 520px; font-size: 10px; }\n  .hero-art {\n    grid-area: art;\n    width: 100%;\n    min-height: 330px;\n    margin-top: 18px;\n    border: 1px solid rgba(76, 111, 153, .82);\n    border-radius: 16px;\n    overflow: hidden;\n    background: linear-gradient(145deg, #162b48, #0b1424 72%);\n  }\n  .hero-art::before { inset: 10px 8px; border-radius: 14px; }\n  .hero-art::after { top: 18px; right: 16px; width: 40px; height: 40px; }\n  .hero-art > img {\n    inset: auto 0 0 0;\n    width: 100%;\n    height: 100%;\n    max-width: none;\n    object-fit: contain;\n    object-position: center bottom;\n  }\n  .hero-stats { margin-top: 12px; }\n  .games-section { padding: 30px 0 28px; }\n  .benefits { margin-top: 12px; }\n  .agent-activity { margin-top: 18px; padding: 34px 0 38px; }\n  .support-section { padding: 40px 0 44px; }\n  .platform-details { padding-top: 30px; padding-bottom: 28px; }\n}\n\n@media (max-width: 430px) {\n  .hero-art { min-height: 290px; margin-top: 16px; }\n  .hero h1 { font-size: clamp(40px, 12.6vw, 52px); }\n}\n\n/* Mobile app dashboard — aligned with the supplied Maanwin platform reference */\n.notification-button {\n  display: grid;\n  place-items: center;\n  width: 42px;\n  height: 42px;\n  margin-left: auto;\n  border: 0;\n  border-radius: 50%;\n  background: #334155;\n  color: #dbeafe;\n  cursor: pointer;\n}\n.notification-button svg { width: 23px; height: 23px; fill: currentColor; }\n\nmain { display: flex; flex-direction: column; }\n.app-home { order: 1; width: min(1120px,calc(100% - 48px)); margin: 24px auto 0; }\n.games-section { order: 2; }\n.hero { order: 3; }\n.benefits { order: 4; }\n.agent-activity { order: 5; }\n.support-section { order: 6; }\n.platform-details { order: 7; }\nfooter { order: 8; }\n\n.balance-card {\n  display: grid;\n  grid-template-columns: 48px minmax(120px,1fr) auto auto;\n  align-items: center;\n  gap: 12px;\n  padding: 13px 15px;\n  border: 1px solid #57729a;\n  border-radius: 17px;\n  background: linear-gradient(135deg,#18243a,#101827);\n  box-shadow: 0 12px 32px rgba(0,0,0,.22);\n}\n.profile-avatar {\n  display: grid;\n  place-items: center;\n  width: 45px;\n  height: 45px;\n  border: 2px solid #738aad;\n  border-radius: 50%;\n  background: linear-gradient(145deg,#f59e0b,#ea580c);\n  color: #fff;\n  font-weight: 900;\n}\n.balance-copy { display: flex; flex-direction: column; min-width: 0; }\n.balance-copy small { color: #9fb0c8; font-size: 11px; font-weight: 700; }\n.balance-copy strong { color: #fff; font-size: 23px; line-height: 1.05; }\n.balance-action {\n  min-width: 108px;\n  padding: 13px 18px;\n  border-radius: 12px;\n  text-align: center;\n  color: #fff;\n  font-size: 13px;\n  font-weight: 900;\n  text-decoration: none;\n}\n.balance-action.deposit { background: linear-gradient(180deg,#ffab2e,#ff7818); }\n.balance-action.withdraw { background: linear-gradient(180deg,#65748a,#374151); }\n\n.app-promo {\n  position: relative;\n  isolation: isolate;\n  display: flex;\n  align-items: center;\n  min-height: 270px;\n  margin-top: 18px;\n  overflow: hidden;\n  border: 1px solid #354761;\n  border-radius: 17px;\n  background:\n    radial-gradient(circle at 76% 55%,rgba(255,132,30,.35),transparent 30%),\n    linear-gradient(135deg,#152335,#0c121d 65%);\n  color: #fff;\n  text-decoration: none;\n}\n.app-promo::after { content: ""; position: absolute; inset: 0; z-index: -1; background: linear-gradient(90deg,#142033 0%,rgba(20,32,51,.9) 40%,transparent 73%); }\n.promo-copy { z-index: 2; display: flex; flex-direction: column; width: 58%; padding: 32px; }\n.promo-copy strong { color: #ff9b24; font-size: clamp(26px,4vw,48px); line-height: 1.03; letter-spacing: -1.5px; }\n.promo-copy em { color: #fff; font-style: normal; }\n.promo-copy small { max-width: 390px; margin-top: 18px; color: #b2bfd1; font-size: 14px; line-height: 1.55; }\n.app-promo img { position: absolute; z-index: 1; right: 5%; top: -90px; width: 230px; height: auto; filter: drop-shadow(0 14px 28px rgba(0,0,0,.5)); }\n.promo-dots { position: absolute; left: 50%; bottom: 10px; color: #1f74ba; letter-spacing: 3px; font-size: 13px; }\n.promo-dots::first-letter { color: #f97316; }\n\n.journey-bar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 14px;\n  margin-top: 18px;\n  padding: 11px 13px;\n  border-radius: 14px;\n  background: #253248;\n  color: #cbd5e1;\n  font-size: 12px;\n  font-weight: 800;\n  letter-spacing: .3px;\n  text-transform: uppercase;\n}\n.journey-bar a { padding: 8px 15px; border-radius: 12px; background: linear-gradient(180deg,#ffad2d,#f97316); color: #fff; text-decoration: none; text-transform: none; }\n.quick-actions { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 12px; margin-top: 18px; }\n.quick-actions > a { display: flex; align-items: center; gap: 12px; min-height: 76px; padding: 12px 16px; border: 1px solid #6680a7; border-radius: 16px; background: #172236; color: #fff; text-decoration: none; }\n.quick-icon { display: grid; place-items: center; width: 48px; height: 48px; flex: 0 0 48px; border-radius: 50%; background: radial-gradient(circle,#ffcf62,#f97316); font-size: 26px; }\n.quick-actions b { display: flex; flex-direction: column; line-height: 1.25; }\n.quick-actions small { margin-top: 3px; color: #ff7f22; font-size: 12px; }\n\n.bottom-nav { display: none; }\n\n@media (max-width: 760px) {\n  body { padding-bottom: 76px; background: #0b1220; }\n  .nav-wrap { min-height: 60px; padding: 9px 13px; border-bottom-color: #425575; border-radius: 0 0 16px 16px; }\n  .brand-logo { width: 143px; height: auto; }\n  .notification-button { width: 36px; height: 36px; }\n  .notification-button svg { width: 20px; height: 20px; }\n  .menu-toggle, #mainNav, .nav-cta { display: none !important; }\n\n  .app-home { width: calc(100% - 26px); margin-top: 18px; }\n  .balance-card { grid-template-columns: 39px minmax(74px,1fr) auto auto; gap: 7px; padding: 10px; }\n  .profile-avatar { width: 37px; height: 37px; font-size: 12px; }\n  .balance-copy small { font-size: 9px; }\n  .balance-copy strong { font-size: 18px; }\n  .balance-action { min-width: 0; padding: 11px 12px; font-size: 10px; }\n\n  .app-promo { min-height: 168px; margin-top: 18px; border-radius: 10px; }\n  .promo-copy { width: 65%; padding: 18px; }\n  .promo-copy strong { font-size: clamp(19px,6vw,27px); letter-spacing: -.8px; }\n  .promo-copy small { max-width: 190px; margin-top: 10px; font-size: 10px; line-height: 1.4; }\n  .app-promo img { right: -2px; top: -71px; width: 135px; }\n  .promo-dots { bottom: 5px; font-size: 9px; }\n  .journey-bar { margin-top: 18px; padding: 8px 9px; font-size: 9px; white-space: nowrap; }\n  .journey-bar a { padding: 7px 12px; }\n  .quick-actions { gap: 9px; }\n  .quick-actions > a { min-height: 60px; padding: 8px; border-radius: 13px; }\n  .quick-icon { width: 38px; height: 38px; flex-basis: 38px; font-size: 20px; }\n  .quick-actions b { font-size: 12px; }\n  .quick-actions small { font-size: 10px; }\n\n  .games-section { margin-top: 8px; padding-top: 22px; border-top: 0; }\n  .games-heading h2 { font-size: 30px; letter-spacing: -1.8px; }\n  .games-section .section-tag { font-size: 8px; }\n  .hero { width: calc(100% - 26px); margin: 18px auto 0; border: 1px solid #354761; border-radius: 17px; }\n  .hero-grid { grid-template-columns: 1fr; }\n  .hero-copy { padding: 16px 12px 20px; }\n  .hero-copy > .kicker, .hero-copy > h1, .hero-copy > .hero-lead { display: none; }\n  .hero-verify { margin-top: 0; }\n  .hero-art, .ticker { display: none; }\n  .hero-stats { margin-top: 16px; }\n\n  .bottom-nav {\n    position: fixed;\n    z-index: 1100;\n    left: 50%;\n    bottom: 0;\n    display: grid;\n    grid-template-columns: repeat(5,1fr);\n    width: min(100%,520px);\n    min-height: 67px;\n    transform: translateX(-50%);\n    border-top: 1px solid #33455f;\n    border-radius: 15px 15px 0 0;\n    background: rgba(18,27,42,.97);\n    box-shadow: 0 -10px 28px rgba(0,0,0,.35);\n    backdrop-filter: blur(12px);\n  }\n  .bottom-nav a { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px; color: #94a3b8; font-size: 17px; text-decoration: none; }\n  .bottom-nav b { font-size: 9px; }\n  .bottom-nav .active { color: #ff7f22; }\n  .bottom-nav-play span { display: grid; place-items: center; width: 50px; height: 50px; margin-top: -25px; border: 2px solid #d88a35; border-radius: 50%; background: linear-gradient(180deg,#ffad2d,#f97316); color: #fff; box-shadow: 0 5px 20px rgba(249,115,22,.35); }\n  .telegram-float { bottom: 82px; }\n}\n\n@media (max-width: 370px) {\n  .balance-card { grid-template-columns: 34px minmax(65px,1fr) auto auto; }\n  .profile-avatar { width: 33px; height: 33px; }\n  .balance-action { padding-inline: 8px; }\n  .quick-actions b { font-size: 11px; }\n}\n\n@media (max-width: 390px) {\n  .nav-cta { display: none; }\n  .hero h1 { font-size: 49px; }\n  .hero-actions { flex-wrap: wrap; }\n  .games-heading h2 { font-size: 39px; }\n  .game-grid { --game-gap: 8px; }\n}\n\n@media (max-width: 520px) {\n  .nav-cta { display: none; }\n  .hero-copy { padding-top: 48px; }\n  .hero h1 { font-size: clamp(43px,14vw,55px); letter-spacing: -3.5px; }\n  .hero-actions { flex-wrap: wrap; }\n  .hero-stats { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 8px; }\n  .hero-stats div { width: auto; margin: 0; padding-right: 8px; }\n  .hero-verify { grid-template-columns: 1fr; }\n  .hero-verify .verify-intro { grid-column: auto; }\n  .hero-access-panel .route-grid { grid-template-columns: 1fr; }\n  .hero-access-panel .route-grid > a { border-right: 0; }\n  .hero-art { min-height: 500px; }\n  .jackpot-card { max-width: calc(100% - 12px); }\n  .verify-box { grid-template-columns: 1fr; }\n  .verify-intro { grid-column: auto; }\n  .verify-box button { width: 100%; }\n  .route-grid strong { overflow-wrap: anywhere; }\n  .section-intro h2, .games-heading h2, .support-copy h2, .activity-heading h2 { font-size: clamp(36px,12vw,45px); }\n  .activity-card { padding: 20px 16px; }\n  .activity-table-card h3, .activity-table-card .activity-index { margin-left: 0; }\n  .activity-table-card table { font-size: 9px; }\n  .activity-table-card th { font-size: 7px; }\n  .faq-list button { grid-template-columns: 30px 1fr auto; gap: 6px; }\n  .faq-list article > div > p { margin-left: 30px; margin-right: 10px; }\n  .platform-details-inner { width: 100%; }\n  .provider-viewport { margin-inline: -4px; }\n}\n\n/* Maanwin platform information and reference provider artwork */\n.platform-details { background: #101115; color: #eeeef0; padding: 52px 24px 38px; }\n.platform-details-inner { width: 100%; max-width: 1120px; min-width: 0; margin: auto; display: grid; grid-template-columns: minmax(0,1.15fr) minmax(0,1fr); gap: 80px; align-items: center; }\n.platform-about, .provider-panel, .provider-viewport { width: 100%; min-width: 0; max-width: 100%; }\n.platform-about > .brand { color: #fff; margin-bottom: 24px; display: inline-flex; }\n.platform-statements { list-style: none; padding: 0; margin: 0; }\n.platform-statements li { position: relative; padding-left: 13px; margin-bottom: 10px; overflow-wrap: anywhere; font: 13px/1.55 Arial, sans-serif; }\n.platform-statements li::before { content: "◆"; position: absolute; left: 0; top: 1px; color: #d4d4d8; font-size: 9px; }\n.platform-warning { color: #ff4949; font: 13px/1.6 Arial, sans-serif; margin: 17px 0 22px; }\n.platform-age { display: grid; place-items: center; width: 44px; height: 44px; border: 2px solid #ff4949; border-radius: 50%; font: bold 15px Arial, sans-serif; color: #ff4949; }\n.provider-panel h2 { margin: 0 0 18px; text-align: center; font: bold 18px/1.25 Arial, sans-serif; letter-spacing: 0; color: #fff; }\n.provider-viewport { overflow: hidden; padding: 2px 0; contain: inline-size; mask-image: linear-gradient(to right,transparent,#000 6%,#000 94%,transparent); -webkit-mask-image: linear-gradient(to right,transparent,#000 6%,#000 94%,transparent); }\n.provider-track { --provider-gap: 10px; display: flex; width: max-content; list-style: none; padding: 0; margin: 0; gap: var(--provider-gap); animation: provider-roll 22s linear infinite; animation-play-state: running !important; will-change: transform; }\n.provider-track li { display: grid; place-items: center; width: 150px; min-height: 66px; flex: 0 0 150px; background: #001b19; border: 1px solid #14504e; border-radius: 11px; box-shadow: inset 0 2px 0 #183936; }\n@keyframes provider-roll { to { transform: translateX(calc(-50% - (var(--provider-gap) / 2))); } }\n.provider-logo { display: block; width: 102px; height: 32px; background-image: url("../images/provider-reference.png"); background-repeat: no-repeat; background-size: 366px 117px; }\n.provider-cq9 { background-position: -14px -32px; }\n.provider-microgaming { background-position: -129px -32px; }\n.provider-jdb { background-position: -244px -32px; }\n.provider-evolution { background-position: -14px -80px; }\n.provider-jili { background-position: -129px -80px; }\n.provider-choice { background-position: -244px -80px; }\n@media (max-width: 760px) {\n .platform-details { padding: 30px 12px; }\n .platform-details-inner { grid-template-columns: 1fr; gap: 28px; max-width: 480px; }\n .platform-statements li, .platform-warning { font-size: 12px; }\n .provider-panel h2 { font-size: 16px; margin-bottom: 14px; }\n .provider-track { --provider-gap: 8px; animation-duration: 18s; }\n .provider-track li { width: 118px; flex-basis: 118px; min-height: 48px; border-radius: 10px; overflow: hidden; }\n}\n@media (max-width: 350px) { .provider-logo { transform: scale(.85); } }\n\n/* Compact phone and device-emulation layout */\n@media (max-width: 760px) {\n  html { scroll-padding-top: 64px; }\n  main { padding-top: 64px; }\n  .nav-wrap { position: fixed; inset: 0 0 auto; width: 100%; max-width: 100%; height: 64px; padding: 0 14px; display: grid; grid-template-columns: minmax(0,1fr) 36px; gap: 9px; box-shadow: 0 5px 16px rgba(23,23,20,.09); }\n  .nav-wrap .brand { gap: 9px; font-size: 16px; }\n  .nav-wrap .brand-logo { width: 138px; height: auto; }\n  .brand-logo-large { width: 185px; height: auto; }\n  .menu-toggle { display: grid; width: 36px; height: 36px; margin: 0; justify-self: end; }\n  .nav-cta { display: none; }\n  nav { top: 60px; left: 12px; right: 12px; padding: 15px; }\n  nav a { padding: 5px 2px; font-size: 11px; }\n\n  .page-shell { width: calc(100% - 28px); }\n  .hero { width: 100%; margin-top: 0; border-radius: 0; }\n  .hero-grid { width: 100%; min-height: 0; }\n  .hero-copy { padding: 16px 16px 22px; }\n  .kicker { gap: 8px; font-size: 8px; letter-spacing: .8px; white-space: nowrap; }\n  .kicker i { width: 21px; }\n  .hero h1 { margin: 20px 0 18px; font-size: clamp(42px,14.5vw,52px); line-height: .86; letter-spacing: -3px; }\n  .hero h1 em { letter-spacing: -2px; }\n  .hero-lead { max-width: 100%; margin: 0; font-size: 12px; line-height: 1.55; }\n  .hero-actions { margin-top: 21px; gap: 13px; flex-wrap: nowrap; }\n  .primary-button { min-height: 44px; padding: 0 13px; gap: 13px; font-size: 8px; }\n  .text-button { white-space: nowrap; font-size: 8px; }\n  .text-button span { width: 27px; height: 27px; margin-right: 6px; }\n  .hero-stats { margin-top: 28px; gap: 0; }\n  .hero-stats div { margin: 0; padding: 0 8px 0 0; }\n  .hero-stats strong { font-size: 18px; }\n  .hero-stats small { font-size: 6px; line-height: 1.35; }\n  .hero-verify { width: 100%; margin-top: 24px; padding: 12px; box-shadow: 5px 5px 0 rgba(255,90,54,.28); }\n  .hero-access-panel { width: 100%; margin-top: 7px; box-shadow: 5px 5px 0 rgba(255,90,54,.28); }\n  .hero-access-panel .route-grid > a { min-height: 58px; padding: 9px 11px; }\n  .hero-art { min-height: 390px; }\n  .hero-art > img { inset: 6px 0 0; width: 100%; height: calc(100% - 6px); object-position: center bottom; }\n  .hero-art::before { inset: 20px -30px 0; }\n  .ring-one { width: 255px; height: 255px; top: 52px; left: 50%; transform: translateX(-50%); }\n  .ring-two { width: 310px; height: 310px; top: 24px; left: 50%; margin-left: -155px; }\n  .jackpot-card { display: none; }\n  .ticker { height: 38px; }\n  .ticker > span { padding: 0 10px; font-size: 6px; }\n\n  .access-section { gap: 24px; padding: 58px 0; }\n  .section-intro h2, .games-heading h2, .support-copy h2, .activity-heading h2 { margin-top: 14px; font-size: clamp(34px,11vw,42px); line-height: .92; letter-spacing: -2.5px; }\n  .access-panel { box-shadow: 5px 5px 0 var(--ink); }\n  .panel-head { padding: 0 11px; }\n  .panel-head small { display: none; }\n  .route-grid > a { min-height: 72px; padding: 12px; }\n  .verify-box { padding: 12px; }\n  .verify-message { grid-template-columns: 32px minmax(0,1fr); gap: 10px; padding: 12px; }\n  .verify-status-icon { width: 32px; height: 32px; font-size: 14px; }\n  .verify-actions { display: grid; grid-template-columns: 1fr; }\n  .verify-actions a, .verify-actions button { width: 100%; }\n\n  .games-section { padding: 16px 0 0; }\n  .games-heading { margin-bottom: 16px; }\n  .game-grid { --game-gap: 8px; }\n  .game-image > span { left: 7px; top: 7px; padding: 5px 6px; }\n  .game-image > b { right: 8px; bottom: 8px; width: 32px; height: 32px; }\n  .benefits { margin-top: 0; }\n  .benefits article { min-height: 106px; padding: 23px 18px; }\n\n  .agent-activity { margin-top: 0; padding: 18px 0 0; }\n  .activity-heading { gap: 12px; margin-bottom: 18px; }\n  .activity-index { margin-bottom: 8px; }\n  .activity-card { padding: 20px 15px; }\n  .activity-copy-card { min-height: 0; }\n  .activity-copy-card:first-child { padding-bottom: 76px; }\n  .telegram-inline { left: 15px; bottom: 18px; }\n  .activity-table-card { padding: 12px 8px; }\n  .activity-table-card table { font-size: 8px; }\n  .activity-table-card th { padding: 8px 2px; font-size: 6px; line-height: 1.35; }\n  .activity-table-card td { padding: 8px 2px; }\n\n  .support-section { gap: 24px; padding: 16px 0 0; }\n  .faq-list button { min-height: 72px; }\n  .platform-details { padding: 16px 14px 32px; overflow: hidden; }\n  .platform-details-inner { grid-template-columns: minmax(0,1fr); gap: 25px; overflow: hidden; }\n  .platform-about > .brand { margin-bottom: 18px; }\n  .platform-statements li, .platform-warning { font-size: 11px; }\n  .provider-track li { width: 112px; flex-basis: 112px; }\n  .footer-inner { min-height: 118px; padding: 22px 0; }\n  .telegram-float { position: fixed !important; width: 48px; height: 48px; right: 16px; bottom: 72px; z-index: 1000; }\n  .telegram-float svg { width: 22px; height: 22px; }\n}\n\n@media (max-width: 340px) {\n  .hero-actions { align-items: stretch; flex-direction: column; }\n  .primary-button { justify-content: space-between; }\n  .text-button { padding: 4px 0; }\n  .hero-art { min-height: 380px; }\n  .game-card { flex-basis: 140px; }\n}\n\n/* Platform-aligned Maanwin theme */\n:root {\n  --ink: #0f1421;\n  --paper: #0b101b;\n  --cream: #f1f7ff;\n  --muted: #9ca3af;\n  --coral: #f97316;\n  --gold: #ffaf2d;\n  --acid: #ffaf2d;\n  --line: rgba(124,147,183,.28);\n  --panel: #12192a;\n  --panel-strong: #19253f;\n  --stroke: #4f5c72;\n  --orange-gradient: linear-gradient(180deg,#ffaf2d 0%,#f97316 100%);\n}\n\nbody { background: #0b101b; color: #fff; }\nbody::before {\n  opacity: 1;\n  background:\n    radial-gradient(circle at 10% 10%,rgba(249,115,22,.14),transparent 27%),\n    radial-gradient(circle at 88% 26%,rgba(43,71,115,.24),transparent 34%),\n    linear-gradient(180deg,#0b101b,#0f1421 45%,#0b101b);\n  mask-image: none;\n}\n\n.nav-wrap {\n  padding-inline: 22px;\n  border: 1px solid rgba(79,92,114,.65);\n  border-top: 0;\n  border-radius: 0 0 18px 18px;\n  background: rgba(18,25,42,.92);\n  box-shadow: 0 8px 28px rgba(0,0,0,.34);\n}\nnav a { color: #d2e4ff; }\nnav a::before { color: var(--gold); }\n.nav-cta, .primary-button, .verify-box > button {\n  border: 0;\n  border-radius: 12px;\n  background: var(--orange-gradient);\n  color: #fff;\n  box-shadow: 0 8px 22px rgba(249,115,22,.22);\n}\n.nav-cta:hover, .primary-button:hover, .verify-box > button:hover {\n  background: linear-gradient(180deg,#ffc050,#ff7e22);\n  color: #fff;\n}\n.nav-cta span { color: #fff; }\n.menu-toggle { border-color: var(--stroke); color: #fff; background: #19253f; }\n\n.hero {\n  border: 1px solid rgba(79,92,114,.72);\n  border-radius: 22px;\n  background:\n    radial-gradient(circle at 78% 36%,rgba(249,115,22,.18),transparent 30%),\n    linear-gradient(145deg,#12192a 0%,#0f1421 48%,#12192a 100%);\n  box-shadow: 0 28px 80px rgba(0,0,0,.38);\n}\n.kicker, .section-tag, .games-section .section-tag { color: var(--gold); }\n.hero h1 { color: #fff; }\n.hero h1 em, .activity-heading h2 em, .support-copy h2 em {\n  color: var(--coral);\n  background: linear-gradient(180deg,#ffaf2d,#f97316);\n  -webkit-background-clip: text;\n  background-clip: text;\n  -webkit-text-fill-color: transparent;\n}\n.hero-lead, .activity-heading > p, .activity-copy-card p { color: #9ca3af; }\n.hero-ring { border-color: rgba(255,175,45,.34); }\n.ring-two { border-color: rgba(249,115,22,.38); }\n.hero-art::before { background: radial-gradient(ellipse at 58% 46%,rgba(249,115,22,.34),rgba(25,37,63,.16) 43%,transparent 72%); }\n\n.hero-verify {\n  border: 1px solid var(--stroke);\n  border-radius: 17px;\n  background: #19253f;\n  box-shadow: none;\n}\n.hero-verify .shield { background: var(--orange-gradient); color: #fff; }\n.hero-verify label {\n  border: 1px solid #4f5c72;\n  border-radius: 11px;\n  background: #12192a;\n  color: #fff;\n}\n.hero-verify input { color: #fff; }\n.hero-verify input::placeholder { color: #627088; }\n.hero-access-panel {\n  overflow: hidden;\n  border: 1px solid #4f5c72;\n  border-radius: 17px;\n  background: #12192a;\n  color: #fff;\n  box-shadow: none;\n}\n.route-grid > a { border-color: rgba(124,147,183,.2); }\n.route-grid > a:hover { background: #19253f; }\n.route-grid > a > b { border-color: #7c93b7; color: #ffaf2d; }\n.route-number { color: #627088; }\n.hero-actions .text-button { color: #d2e4ff; }\n.text-button span { border-color: #4f5c72; color: #ffaf2d; background: #19253f; }\n.hero-stats { gap: 10px; }\n.hero-stats div {\n  min-width: 0;\n  margin: 0;\n  padding: 12px 16px;\n  border: 1px solid rgba(79,92,114,.58);\n  border-radius: 12px;\n  background: rgba(25,37,63,.72);\n}\n.hero-stats strong { color: #ffaf2d; font-family: inherit; font-weight: 800; }\n.hero-stats small { color: #9ca3af; }\n.jackpot-card {\n  border: 1px solid #7c93b7;\n  border-radius: 15px;\n  background: #19253f;\n  color: #fff;\n  box-shadow: 0 14px 34px rgba(0,0,0,.35);\n  transform: none;\n}\n.jackpot-card a { background: var(--orange-gradient); color: #fff; }\n.ticker { background: #19253f; color: #f1f7ff; }\n.ticker > span { background: var(--orange-gradient); color: #fff; }\n\n.games-section {\n  border-block-color: #253248;\n  background: #0f1421;\n}\n.games-section::before { opacity: .12; filter: saturate(.8) hue-rotate(340deg); }\n.games-section::after { background: linear-gradient(180deg,rgba(15,20,33,.5),#0f1421 92%); }\n.game-card {\n  border: 1px solid #4f5c72;\n  border-radius: 13px;\n  background: #1f2937;\n  box-shadow: 0 12px 28px rgba(0,0,0,.3);\n}\n.game-card::before { border-radius: 9px; border-color: rgba(124,147,183,.16); }\n.game-card:hover { border-color: #ffaf2d; box-shadow: 0 18px 38px rgba(0,0,0,.48),0 0 24px rgba(249,115,22,.18); }\n.game-image { border-radius: 9px; background: #12192a; }\n.game-image > span { border-color: #ffaf2d; background: rgba(15,20,33,.86); color: #ffcf73; }\n.game-image > b { border: 0; background: var(--orange-gradient); color: #fff; }\n\n.benefits { gap: 14px; border: 0; }\n.benefits article {\n  min-height: 138px;\n  border: 1px solid #4f5c72;\n  border-radius: 17px;\n  background: #19253f;\n  color: #fff;\n}\n.benefits article:last-child { border: 1px solid #4f5c72; }\n.benefits span { color: #ffaf2d; }\n.benefits p { color: #9ca3af; }\n\n.agent-activity { background: #0f1421; }\n.activity-card {\n  border: 1px solid #4f5c72;\n  border-radius: 17px;\n  background: #19253f;\n  box-shadow: none;\n}\n.activity-index { color: #ffaf2d; }\n.activity-copy-card li { color: #d2e4ff; }\n.activity-copy-card li::before { color: #f97316; }\n.activity-copy-card p strong { color: #ffaf2d; }\n.activity-accent { border-color: #f97316; background: linear-gradient(145deg,#f97316,#c9570e); box-shadow: none; }\n.activity-accent .activity-index { color: #fff3dc; }\n.activity-table-card { background: #19253f; color: #fff; }\n.activity-table-card th { background: var(--orange-gradient); }\n.activity-table-card td { border-color: #33435d; }\n.activity-table-card tbody tr:nth-child(even) { background: #12192a; }\n.activity-table-card tbody tr:hover { background: #2e3c4e; }\n\n.support-section { color: #fff; }\n.support-copy > p:not(.section-tag), .faq-list article > div > p { color: #9ca3af; }\n.support-copy > a { border-color: #f97316; color: #ffaf2d; }\n.faq-list { border-top-color: #4f5c72; }\n.faq-list article { border-bottom-color: #4f5c72; }\n.faq-list button i { border-color: #7c93b7; color: #ffaf2d; }\n.faq-list article.open button i { border-color: #f97316; background: var(--orange-gradient); }\n\n.platform-details, footer { background: #090d16; }\n.platform-details { border-top: 1px solid #253248; }\n.platform-statements li { color: #d2e4ff; }\n.platform-statements li::before { color: #f97316; }\n.provider-track li { border-color: #4f5c72; background: #19253f; box-shadow: inset 0 1px rgba(255,255,255,.05); }\n.footer-inner p, .footer-inner > a:last-child { color: #7f9ab5; }\n\n.verify-message { border-radius: 12px; box-shadow: none; }\n.verify-message.safe { border-color: #18b660; background: #102d25; color: #fff; }\n.verify-message.incomplete { border-color: #ffaf2d; background: #33270f; color: #fff; }\n.verify-message.unsafe { border-color: #fb5b5b; background: #351b20; color: #fff; }\n.verify-result p, .verify-domain { color: #c2ccda; }\n.verify-actions .verify-primary { border-color: #f97316; background: var(--orange-gradient); color: #fff; }\n.verify-actions .verify-secondary { border-color: #7c93b7; color: #fff; }\n\n@media (max-width: 1050px) {\n  nav { border-color: #4f5c72; border-radius: 14px; background: #19253f; box-shadow: 0 18px 42px rgba(0,0,0,.42); }\n}\n\n@media (max-width: 760px) {\n  body { background: #0f1421; }\n  .nav-wrap { border-inline: 0; border-radius: 0 0 17px 17px; background: rgba(18,25,42,.96); box-shadow: 0 6px 22px rgba(0,0,0,.36); }\n  .hero { border-inline: 0; border-radius: 0 0 20px 20px; }\n  .hero-copy { padding-top: 22px; }\n  .hero h1 { line-height: .9; }\n  .hero-verify, .hero-access-panel { box-shadow: none; }\n  .hero-stats { gap: 7px; }\n  .hero-stats div { padding: 10px 8px; }\n  .games-section { padding-top: 25px; }\n  .benefits { gap: 10px; padding-block: 18px; }\n  .benefits article, .benefits article:last-child { min-height: 100px; border: 1px solid #4f5c72; }\n  .agent-activity { padding-top: 28px; }\n  .activity-card { box-shadow: none; }\n  .platform-details { padding-top: 25px; }\n}\n\n/* Keep the app navigation independent from the legacy header nav rules. */\n@media (max-width: 760px) {\n  nav.bottom-nav {\n    top: auto;\n    right: auto;\n    bottom: 0;\n    left: 50%;\n    margin: 0;\n    padding: 0;\n    border-right: 0;\n    border-bottom: 0;\n    border-left: 0;\n  }\n  nav.bottom-nav a { padding: 0; font-size: 17px; }\n  nav.bottom-nav a::before { content: none; }\n  .games-heading h2 { font-size: 31px; line-height: .96; letter-spacing: -1.5px; }\n  .app-promo img { top: 0; right: 0; width: 45%; height: 100%; object-fit: cover; object-position: center 42%; }\n}\n\n/* Roll back the dashboard experiment: retain the original Maanwin landing layout. */\nmain { display: block; }\n\n@media (max-width: 760px) {\n  body { padding-bottom: 0; }\n  .menu-toggle { display: grid !important; }\n  #mainNav { display: none; }\n  #mainNav.open {\n    display: grid !important;\n    z-index: 120;\n  }\n  .hero {\n    width: 100%;\n    margin-top: 0;\n    border-inline: 0;\n    border-radius: 0 0 20px 20px;\n  }\n  .hero-copy { padding: 22px 16px 22px; }\n  .hero-copy > .kicker { display: flex; }\n  .hero-copy > h1, .hero-copy > .hero-lead { display: block; }\n  .hero-art { display: block; }\n  .ticker { display: flex; }\n  .games-section { margin-top: 0; padding-top: 25px; border-top: 1px solid #253248; }\n  .games-heading h2 { font-size: clamp(36px,12vw,45px); line-height: .9; letter-spacing: -3px; }\n}\n\n/* Improve readability inside the orange agent card. */\n.activity-card.activity-accent { color: #fff; }\n.activity-card.activity-accent h3,\n.activity-card.activity-accent p,\n.activity-card.activity-accent li { color: #fff; }\n.activity-card.activity-accent .activity-index { color: #fff1c7; }\n.activity-card.activity-accent li::before { color: #ffe09a; }\n\n/* ===== Hero refresh v38: orange / midnight Maanwin campaign ===== */\n.hero {\n  position: relative;\n  width: min(1420px, calc(100% - 24px));\n  margin-top: 14px;\n  overflow: hidden;\n  border: 1px solid rgba(255,145,42,.28);\n  border-radius: 24px;\n  background:\n    radial-gradient(circle at 73% 34%, rgba(255,133,26,.24), transparent 25%),\n    radial-gradient(circle at 92% 78%, rgba(249,115,22,.12), transparent 28%),\n    linear-gradient(135deg,#090e18 0%,#0c1422 47%,#070b12 100%);\n  box-shadow: 0 30px 90px rgba(0,0,0,.46), inset 0 1px rgba(255,255,255,.035);\n}\n.hero::before,\n.hero::after {\n  content: "";\n  position: absolute;\n  pointer-events: none;\n  z-index: 1;\n}\n.hero::before {\n  width: 820px;\n  height: 3px;\n  right: -180px;\n  top: 32%;\n  transform: rotate(-35deg);\n  background: linear-gradient(90deg, transparent, rgba(255,137,28,.92), transparent);\n  box-shadow: 0 0 28px rgba(255,120,20,.5), 0 140px 0 rgba(255,121,20,.2), 0 280px 0 rgba(255,121,20,.16);\n}\n.hero::after {\n  width: 430px;\n  height: 430px;\n  right: 8.5%;\n  top: 14%;\n  border: 1px solid rgba(255,156,50,.2);\n  border-radius: 50%;\n  box-shadow: 0 0 0 46px rgba(255,156,50,.035), 0 0 90px rgba(255,119,20,.15);\n}\n.hero-grid {\n  position: relative;\n  z-index: 2;\n  width: min(1280px, calc(100% - 56px));\n  min-height: 770px;\n  grid-template-columns: minmax(0,1.04fr) minmax(430px,.96fr);\n  gap: 20px;\n}\n.hero-copy {\n  padding: 68px 8px 48px 0;\n}\n.hero-intro { position: relative; z-index: 6; }\n.hero .kicker {\n  color: #ffad31;\n  font-weight: 900;\n  letter-spacing: 1.7px;\n}\n.hero h1 {\n  margin: 25px 0 23px;\n  max-width: 670px;\n  font-size: clamp(72px,6.7vw,104px);\n  line-height: .82;\n  letter-spacing: -7px;\n  text-shadow: 0 8px 26px rgba(0,0,0,.28);\n}\n.hero h1 em {\n  color: #ff8c1e;\n  background: linear-gradient(180deg,#ffb33b 3%,#ff6e16 96%);\n  -webkit-background-clip: text;\n  background-clip: text;\n  -webkit-text-fill-color: transparent;\n  filter: drop-shadow(0 8px 14px rgba(255,112,20,.15));\n}\n.hero-lead {\n  max-width: 555px;\n  color: #bcc7d8;\n  font-size: 14px;\n  line-height: 1.65;\n}\n.hero-verify {\n  width: min(590px,100%);\n  margin-top: 30px;\n  padding: 13px;\n  border: 1px solid #3d4f6d;\n  border-radius: 17px;\n  background: linear-gradient(180deg,rgba(27,40,64,.97),rgba(16,26,43,.97));\n  box-shadow: 0 18px 42px rgba(0,0,0,.24), inset 0 1px rgba(255,255,255,.035);\n}\n.hero-verify .shield {\n  width: 36px;\n  height: 36px;\n  background: linear-gradient(180deg,#ffb43a,#ff7319);\n  box-shadow: 0 7px 18px rgba(255,116,24,.24);\n}\n.hero-verify label {\n  border-color: #465a7a;\n  background: #0f1727;\n}\n.hero-verify > button {\n  min-width: 106px;\n  border-radius: 10px;\n  background: linear-gradient(180deg,#ffb034,#ff7319);\n  box-shadow: 0 7px 20px rgba(255,112,20,.2);\n}\n.hero-access-panel {\n  width: min(590px,100%);\n  margin-top: 9px;\n  border-color: #3d4f6d;\n  border-radius: 17px;\n  background: rgba(13,22,37,.94);\n  box-shadow: 0 18px 42px rgba(0,0,0,.18);\n}\n.hero-access-panel .route-grid > a {\n  min-height: 61px;\n  padding: 10px 13px;\n}\n.hero-access-panel .route-grid > a:hover {\n  background: linear-gradient(90deg,rgba(255,128,24,.12),rgba(25,37,63,.9));\n}\n.hero-access-panel .route-grid > a > b {\n  border-color: #d88929;\n  color: #ff9e2e;\n  background: rgba(255,145,30,.045);\n}\n.hero-actions {\n  margin-top: 27px;\n  gap: 22px;\n}\n.hero .primary-button {\n  min-height: 56px;\n  padding-inline: 24px;\n  border-radius: 13px;\n  background: linear-gradient(180deg,#ffb236,#ff7018);\n  box-shadow: 0 12px 30px rgba(255,111,20,.24);\n}\n.hero .primary-button:hover {\n  color: #fff;\n  background: linear-gradient(180deg,#ffc454,#ff8427);\n  transform: translateY(-2px);\n}\n.hero .text-button { color: #dce7f6; }\n.hero .text-button span {\n  border-color: #8d6336;\n  background: rgba(255,143,34,.09);\n  color: #ffad31;\n}\n.hero-stats {\n  margin-top: 32px;\n  gap: 10px;\n}\n.hero-stats div {\n  min-width: 0;\n  width: 143px;\n  min-height: 71px;\n  margin: 0;\n  padding: 12px 14px;\n  border: 1px solid rgba(82,103,136,.72);\n  border-radius: 13px;\n  background: linear-gradient(180deg,rgba(27,40,64,.92),rgba(16,25,42,.92));\n}\n.hero-stats strong { color: #ffad31; font-size: 22px; }\n.hero-stats small { color: #95a3b7; }\n.hero-art {\n  position: relative;\n  min-height: 770px;\n  overflow: visible;\n  isolation: isolate;\n}\n.hero-art::before {\n  inset: 8% -10% 3% -4%;\n  z-index: -2;\n  border-radius: 42%;\n  background:\n    radial-gradient(circle at 48% 37%,rgba(255,153,42,.35),transparent 30%),\n    radial-gradient(circle at 58% 58%,rgba(255,104,12,.19),transparent 45%);\n  filter: blur(2px);\n}\n.hero-art::after {\n  content: "₹";\n  position: absolute;\n  z-index: 2;\n  top: 118px;\n  right: 32px;\n  width: 76px;\n  height: 76px;\n  display: grid;\n  place-items: center;\n  border: 2px solid #ffb43a;\n  border-radius: 50%;\n  background: radial-gradient(circle at 35% 30%,#ffd46a,#ff9d21 45%,#e95e0c 80%);\n  color: #fff7dc;\n  box-shadow: 0 0 0 7px rgba(255,143,27,.12),0 12px 35px rgba(255,105,12,.25);\n  font: 900 38px Georgia,serif;\n  transform: rotate(13deg);\n}\n.hero-art > img {\n  position: absolute;\n  z-index: 4;\n  inset: auto -70px -16px auto;\n  width: 114%;\n  height: auto;\n  max-width: none;\n  object-fit: contain;\n  object-position: right bottom;\n  filter: saturate(1.04) contrast(1.04) drop-shadow(0 32px 30px rgba(0,0,0,.52));\n}\n.hero-art-logo {\n  position: absolute;\n  z-index: 7;\n  top: 39px;\n  right: 18px;\n  width: 210px;\n  padding: 11px 14px;\n  border: 1px solid rgba(255,160,55,.23);\n  border-radius: 14px;\n  background: rgba(8,14,24,.62);\n  box-shadow: 0 12px 32px rgba(0,0,0,.24);\n  backdrop-filter: blur(10px);\n}\n.hero-art-logo img { display: block; width: 100%; height: auto; }\n.hero-ring { display: none; }\n.jackpot-card {\n  right: 9px;\n  bottom: 25px;\n  width: 318px;\n  min-height: 86px;\n  border-color: #597092;\n  background: linear-gradient(180deg,rgba(29,42,66,.97),rgba(13,2