 0 18px 2px;\n    z-index: 5;\n  }\n  .hero .kicker {\n    gap: 7px;\n    font-size: 6px;\n    letter-spacing: .9px;\n    line-height: 1.45;\n  }\n  .hero .kicker i { width: 20px; }\n  .hero h1 {\n    margin: 15px 0 12px;\n    font-size: clamp(40px,12.8vw,58px);\n    line-height: .86;\n    letter-spacing: -3.8px;\n  }\n  .hero h1 em { letter-spacing: -2.2px; }\n  .hero-lead {\n    max-width: 100%;\n    margin: 0;\n    color: #aebcd0;\n    font-size: 10.5px;\n    line-height: 1.55;\n  }\n  .hero-art {\n    grid-area: art;\n    align-self: stretch;\n    min-height: 285px;\n    z-index: 3;\n  }\n  .hero-art::before { inset: 12% -70% 4% -65%; }\n  .hero-art::after {\n    top: 47px;\n    right: -2px;\n    width: 44px;\n    height: 44px;\n    border-width: 1px;\n    font-size: 20px;\n    box-shadow: 0 0 0 4px rgba(255,143,27,.1),0 8px 24px rgba(255,105,12,.18);\n  }\n  .hero-art > img {\n    inset: auto -62% -3px auto;\n    width: 186%;\n    height: auto;\n    max-height: none;\n    object-fit: contain;\n  }\n  .hero-art-logo { display: none; }\n  .jackpot-card { display: none; }\n  .hero-verify {\n    grid-area: verify;\n    width: 100%;\n    margin-top: 6px;\n    padding: 11px;\n    grid-template-columns: 1fr auto;\n    border-radius: 15px;\n  }\n  .hero-verify .verify-intro { grid-column: 1 / -1; }\n  .hero-verify > button { min-width: 96px; }\n  .hero-access-panel {\n    grid-area: access;\n    width: 100%;\n    margin-top: 8px;\n    border-radius: 15px;\n  }\n  .hero-access-panel .route-grid { grid-template-columns: 1fr; }\n  .hero-access-panel .route-grid > a {\n    min-height: 50px;\n    padding: 8px 11px;\n    border-right: 0;\n  }\n  .hero-actions {\n    grid-area: actions;\n    margin-top: 17px;\n    display: grid;\n    grid-template-columns: minmax(0,1fr) auto;\n    gap: 10px;\n  }\n  .hero .primary-button {\n    min-height: 51px;\n    justify-content: center;\n    padding-inline: 18px;\n  }\n  .hero .text-button {\n    min-height: 51px;\n    display: inline-flex;\n    align-items: center;\n    white-space: nowrap;\n  }\n  .hero-stats {\n    grid-area: stats;\n    margin-top: 14px;\n    display: grid;\n    grid-template-columns: repeat(3,minmax(0,1fr));\n    gap: 7px;\n  }\n  .hero-stats div {\n    width: auto;\n    min-height: 65px;\n    padding: 9px 7px;\n    text-align: center;\n    justify-items: center;\n  }\n  .hero-stats strong { font-size: 19px; }\n  .hero-stats small { font-size: 6px; line-height: 1.35; }\n  .ticker { height: 39px; }\n  .ticker > span { padding-inline: 15px; font-size: 7px; }\n  .ticker p { padding-left: 22px; font-size: 7px; }\n}\n\n@media (max-width: 430px) {\n  .hero-grid {\n    grid-template-columns: minmax(0,1fr) minmax(118px,39%);\n    gap: 0 4px;\n  }\n  .hero-intro { padding-top: 24px; }\n  .hero h1 { font-size: clamp(39px,12.4vw,50px); }\n  .hero-lead { font-size: 9.6px; }\n  .hero-art { min-height: 255px; }\n  .hero-art > img { right: -70%; width: 197%; }\n  .hero-verify { grid-template-columns: 1fr; }\n  .hero-verify .verify-intro { grid-column: auto; }\n  .hero-verify > button { width: 100%; }\n  .hero-actions { grid-template-columns: 1fr; }\n  .hero .text-button { justify-content: center; min-height: 36px; }\n}\n\n@media (max-width: 350px) {\n  .hero-grid { grid-template-columns: minmax(0,1fr) 112px; }\n  .hero h1 { font-size: 38px; }\n  .hero-art > img { right: -82%; width: 220%; }\n}\n\n/* ===== Hero final alignment v39 — matches supplied desktop + phone UI ===== */\n/* Keep the document in its natural HTML order. Older app-dashboard rules are intentionally neutralised. */\nmain { display: block; padding-top: 0; }\n.hero, .games-section, .benefits, .agent-activity, .support-section, .platform-details, footer { order: initial; }\n\n/* Header visually joins the hero on desktop. */\n.nav-wrap {\n  position: relative;\n  top: auto;\n  z-index: 100;\n  width: min(1400px, calc(100% - 28px));\n  height: 82px;\n  margin: 14px auto 0;\n  padding: 0 34px;\n  gap: 30px;\n  border: 1px solid rgba(91,113,147,.7);\n  border-bottom: 0;\n  border-radius: 24px 24px 0 0;\n  background: linear-gradient(180deg,rgba(10,16,27,.99),rgba(11,18,30,.99));\n  box-shadow: 0 16px 42px rgba(0,0,0,.28);\n}\n.nav-wrap .brand-logo { width: 215px; }\n.nav-wrap nav { margin: 0 auto; display: flex; align-items: center; gap: 39px; }\n.nav-wrap nav a {\n  position: relative;\n  padding: 31px 0 27px;\n  color: #dce6f4;\n  font-size: 14px;\n  font-weight: 700;\n  text-transform: none;\n}\n.nav-wrap nav a::before { content: none; }\n.nav-wrap nav a:first-child::after {\n  content: "";\n  position: absolute;\n  left: 0;\n  right: 0;\n  bottom: 20px;\n  height: 4px;\n  border-radius: 99px;\n  background: linear-gradient(90deg,#ffad2f,#ff7619);\n}\n.nav-actions { display: flex; align-items: center; gap: 14px; }\n.nav-login, .nav-register {\n  min-width: 94px;\n  min-height: 44px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 13px;\n  font-size: 13px;\n  font-weight: 850;\n  transition: .2s ease;\n}\n.nav-login { border: 1px solid #4e6484; color: #fff; background: rgba(16,26,43,.86); }\n.nav-register { border: 1px solid #ff9b2b; color: #fff; background: linear-gradient(180deg,#ffaf32,#ff7217); box-shadow: 0 8px 24px rgba(255,111,20,.24); }\n.nav-login:hover, .nav-register:hover { transform: translateY(-2px); }\n\n.hero {\n  width: min(1400px, calc(100% - 28px));\n  margin: 0 auto;\n  border-top: 0;\n  border-radius: 0 0 24px 24px;\n  overflow: hidden;\n  background:\n    radial-gradient(circle at 79% 26%,rgba(255,132,25,.27),transparent 24%),\n    radial-gradient(circle at 65% 82%,rgba(255,100,12,.14),transparent 34%),\n    linear-gradient(135deg,#080d16 0%,#0d1625 52%,#070b12 100%);\n}\n.hero-grid {\n  width: min(1288px, calc(100% - 72px));\n  min-height: 805px;\n  margin: 0 auto;\n  grid-template-columns: minmax(0,1.02fr) minmax(470px,.98fr);\n  gap: 18px;\n}\n.hero-copy { padding: 62px 0 34px; }\n.hero .kicker { font-size: 9px; letter-spacing: 1.8px; }\n.hero h1 {\n  max-width: 620px;\n  margin: 25px 0 23px;\n  font-size: clamp(74px,6.55vw,102px);\n  line-height: .82;\n  letter-spacing: -6.8px;\n}\n.hero h1 em { letter-spacing: -4.6px; }\n.hero-lead { max-width: 565px; font-size: 14px; line-height: 1.62; }\n.hero-verify, .hero-access-panel { width: min(600px,100%); }\n.hero-verify { margin-top: 28px; }\n.hero-access-panel { margin-top: 9px; }\n.hero-access-panel .route-grid { grid-template-columns: repeat(2,minmax(0,1fr)); }\n.hero-access-panel .route-grid > a { min-height: 59px; }\n.hero-actions { margin-top: 24px; }\n.hero .primary-button { min-width: 232px; min-height: 56px; justify-content: center; }\n.hero-stats { margin-top: 25px; display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 11px; max-width: 600px; }\n.hero-stats div {\n  width: auto;\n  min-height: 72px;\n  padding: 10px 11px;\n  display: grid;\n  grid-template-columns: 28px auto;\n  grid-template-areas: "icon value" "icon label";\n  align-items: center;\n  justify-content: start;\n  column-gap: 9px;\n  text-align: left;\n}\n.stat-icon {\n  grid-area: icon;\n  width: 28px;\n  height: 28px;\n  display: grid;\n  place-items: center;\n  border-radius: 50%;\n  background: rgba(255,145,31,.12);\n  color: #ffad31;\n  font-size: 12px;\n}\n.stat-game { font-size: 10px; }\n.stat-users { font-size: 7px; letter-spacing: -3px; padding-right: 3px; }\n.hero-stats strong { grid-area: value; align-self: end; font-size: 20px; line-height: 1; }\n.hero-stats small { grid-area: label; align-self: start; margin-top: 3px; font-size: 6.4px; line-height: 1.2; white-space: nowrap; }\n\n/* Hero art: keep the whole mascot inside the card instead of cutting its right side. */\n.hero-art {\n  min-height: 805px;\n  overflow: visible;\n}\n.hero-art > img {\n  inset: auto 0 -10px auto;\n  width: min(760px,119%);\n  height: auto;\n  max-width: none;\n  object-fit: contain;\n  object-position: center bottom;\n  transform: none;\n}\n.hero-art::before { inset: 6% -3% 1% -8%; }\n.hero-art::after { top: 115px; right: 40px; width: 70px; height: 70px; }\n.hero-art-logo { display: none; }\n.jackpot-card { right: 4px; bottom: 22px; width: 315px; transform: none; }\n.ticker { height: 42px; }\n\n@media (max-width: 1120px) and (min-width: 761px) {\n  .nav-wrap { padding-inline: 24px; gap: 20px; }\n  .nav-wrap .brand-logo { width: 190px; }\n  .nav-wrap nav { gap: 23px; }\n  .nav-wrap nav a { font-size: 12px; }\n  .nav-login, .nav-register { min-width: 78px; }\n  .hero-grid { width: calc(100% - 48px); grid-template-columns: minmax(0,1.06fr) minmax(370px,.94fr); min-height: 740px; }\n  .hero-copy { padding-top: 50px; }\n  .hero h1 { font-size: clamp(66px,7.5vw,84px); }\n  .hero-art { min-height: 740px; }\n  .hero-art > img { width: 130%; right: -5%; bottom: -4px; }\n}\n\n/* Phone layout — header + hero are contiguous, no blank strip, and mascot stays inside viewport. */\n@media (max-width: 760px) {\n  html { scroll-padding-top: 64px; }\n  body { padding-bottom: 0; }\n  main { padding-top: 64px; }\n  .nav-wrap {\n    position: fixed;\n    inset: 0 0 auto;\n    width: 100%;\n    max-width: 100%;\n    height: 64px;\n    min-height: 64px;\n    margin: 0;\n    padding: 0 16px;\n    display: grid;\n    grid-template-columns: minmax(0,1fr) 38px;\n    align-items: center;\n    gap: 10px;\n    border: 0;\n    border-bottom: 1px solid #31445f;\n    border-radius: 0;\n    background: rgba(11,18,30,.98);\n    box-shadow: 0 6px 20px rgba(0,0,0,.3);\n  }\n  .nav-wrap .brand-logo { width: 142px; }\n  .nav-actions { display: none !important; }\n  .menu-toggle {\n    display: grid !important;\n    place-items: center;\n    width: 36px;\n    height: 36px;\n    margin: 0;\n    justify-self: end;\n    border: 1px solid #48617f;\n    border-radius: 50%;\n    background: #17243a;\n    color: #fff;\n    font-size: 17px;\n    cursor: pointer;\n  }\n  .nav-wrap nav,\n  .nav-wrap #mainNav {\n    display: none !important;\n    position: absolute;\n   