-width: none;\n    max-height: none;\n    object-fit: contain;\n    object-position: center bottom;\n  }\n  .jackpot-card, .hero-art-logo { display: none; }\n  .hero-verify {\n    grid-area: verify;\n    width: 100%;\n    margin-top: 0;\n    padding: 10px;\n    display: grid;\n    grid-template-columns: 1fr;\n    gap: 8px;\n    border-radius: 14px;\n  }\n  .hero-verify .verify-intro { grid-column: auto; }\n  .hero-verify label { width: 100%; height: 42px; }\n  .hero-verify > button { width: 100%; min-width: 0; height: 43px; border-radius: 10px; }\n  .hero-access-panel { grid-area: access; width: 100%; margin-top: 8px; border-radius: 14px; }\n  .hero-access-panel .route-grid { grid-template-columns: 1fr; }\n  .hero-access-panel .route-grid > a { min-height: 47px; padding: 7px 10px; border-right: 0; }\n  .hero-access-panel .route-grid strong { font-size: 10px; }\n  .hero-access-panel .route-number { font-size: 8px; }\n  .hero-access-panel .route-grid > a > b { width: 27px; height: 27px; }\n  .hero-actions {\n    grid-area: actions;\n    margin-top: 15px;\n    display: grid;\n    grid-template-columns: 1fr;\n    gap: 7px;\n  }\n  .hero .primary-button { width: 100%; min-width: 0; min-height: 49px; justify-content: center; }\n  .hero .text-button { min-height: 34px; display: flex; align-items: center; justify-content: center; }\n  .hero-stats {\n    grid-area: stats;\n    max-width: none;\n    margin-top: 10px;\n    grid-template-columns: repeat(3,minmax(0,1fr));\n    gap: 7px;\n  }\n  .hero-stats div {\n    min-height: 77px;\n    padding: 8px 5px;\n    grid-template-columns: 1fr;\n    grid-template-areas: "icon" "value" "label";\n    justify-items: center;\n    align-content: center;\n    row-gap: 3px;\n    text-align: center;\n  }\n  .stat-icon { width: 25px; height: 25px; font-size: 10px; }\n  .hero-stats strong { font-size: 18px; }\n  .hero-stats small { margin: 0; font-size: 5.8px; white-space: normal; }\n  .ticker { display: none; }\n}\n\n@media (max-width: 430px) {\n  .hero-grid { grid-template-columns: minmax(0,55%) minmax(0,45%); padding-inline: 12px; }\n  .hero-intro { padding-top: 23px; }\n  .hero h1 { font-size: clamp(38px,12vw,47px); }\n  .hero-lead { font-size: 8.5px; }\n  .hero-art { min-height: 260px; }\n  .hero-art > img { width: 143%; right: -22%; }\n}\n\n@media (max-width: 360px) {\n  .nav-wrap .brand-logo { width: 132px; }\n  .hero-grid { grid-template-columns: minmax(0,57%) minmax(0,43%); padding-inline: 10px; }\n  .hero h1 { font-size: 36px; letter-spacing: -2.5px; }\n  .hero-lead { font-size: 8px; }\n  .hero-art { min-height: 245px; }\n  .hero-art > img { width: 141%; right: -24%; }\n}\n\n/* v39.1 finishing corrections: remove the phone header gap and never clip the mascot on the right. */\n.ticker { display: none; }\n.hero-art > img { right: 0; bottom: 0; }\n@media (max-width: 760px) {\n  .hero-art > img { right: 0; bottom: 0; width: 155%; }\n}\n@media (max-width: 430px) {\n  .hero-art > img { right: 0; width: 158%; }\n}\n@media (max-width: 360px) {\n  .hero-art > img { right: 0; width: 160%; }\n}\n\n/* ===== v40 spacing + mobile auth fixes =====\n   Compact the vertical rhythm without touching any functional JS/links. */\n\n/* Desktop/tablet section rhythm */\n@media (min-width: 761px) {\n  .games-section {\n    padding-top: 52px;\n    padding-bottom: 48px;\n  }\n  .games-heading { margin-bottom: 28px; }\n\n  .benefits {\n    margin-top: 34px;\n  }\n\n  .agent-activity {\n    margin-top: 38px;\n    padding-top: 56px;\n    padding-bottom: 58px;\n  }\n  .activity-heading { margin-bottom: 38px; }\n\n  .support-section {\n    padding-top: 58px;\n    padding-bottom: 62px;\n  }\n\n  .platform-details {\n    padding-top: 36px;\n    padding-bottom: 34px;\n  }\n}\n\n/* Phone header: keep Login + Register visible beside the menu button. */\n@media (max-width: 760px) {\n  .nav-wrap {\n    grid-template-columns: minmax(0,1fr) auto 36px;\n    gap: 7px;\n    padding-inline: 12px;\n  }\n\n  .nav-actions {\n    display: flex !important;\n    align-items: center;\n    justify-content: flex-end;\n    gap: 5px;\n    min-width: 0;\n  }\n  .nav-login,\n  .nav-register {\n    min-width: 49px;\n    min-height: 30px;\n    padding: 0 8px;\n    border-radius: 9px;\n    font-size: 8.5px;\n    line-height: 1;\n    white-space: nowrap;\n  }\n  .nav-register { min-width: 56px; }\n\n  /* Tighter but still breathable section spacing on phone. */\n  .games-section {\n    margin-top: 0;\n    padding-top: 24px;\n    padding-bottom: 24px;\n  }\n  .games-heading { margin-bottom: 18px; }\n\n  .benefits {\n    margin-top: 14px;\n    padding-top: 0;\n    padding-bottom: 0;\n  }\n\n  .agent-activity {\n    margin-top: 18px;\n    padding-top: 28px;\n    padding-bottom: 30px;\n  }\n  .activity-heading { margin-bottom: 24px; }\n\n  .support-section {\n    padding-top: 30px;\n    padding-bottom: 34px;\n  }\n\n  .platform-details {\n    padding-top: 28px;\n    padding-bottom: 28px;\n  }\n}\n\n@media (max-width: 430px) {\n  .nav-wrap .brand-logo { width: 126px; }\n  .nav-login,\n  .nav-register {\n    min-width: 44px;\n    min-height: 29px;\n    padding-inline: 6px;\n    font-size: 7.8px;\n  }\n  .nav-register { min-width: 52px; }\n}\n\n@media (max-width: 360px) {\n  .nav-wrap { grid-template-columns: minmax(0,1fr) auto 34px; gap: 5px; padding-inline: 9px; }\n  .nav-wrap .brand-logo { width: 112px; }\n  .menu-toggle { width: 34px; height: 34px; }\n  .nav-actions { gap: 4px; }\n  .nav-login,\n  .nav-register {\n    min-width: 40px;\n    min-height: 28px;\n    padding-inline: 5px;\n    font-size: 7.2px;\n  }\n  .nav-register { min-width: 47px; }\n}\n\n/* ===== v41 mobile header polish =====\n   Final responsive auth/header alignment. Keeps all links and JS logic unchanged. */\n@media (max-width: 760px) {\n  .nav-wrap {\n    height: 66px;\n    min-height: 66px;\n    padding: 0 11px;\n    display: flex !important;\n    align-items: center;\n    gap: 7px;\n    overflow: visible;\n  }\n\n  .nav-wrap .brand {\n    flex: 0 1 auto;\n    min-width: 0;\n    margin-right: auto;\n  }\n\n  .nav-wrap .brand-logo {\n    width: clamp(112px, 30vw, 138px);\n    max-width: 100%;\n    height: auto;\n  }\n\n  .nav-actions {\n    display: flex !important;\n    flex: 0 0 auto;\n    align-items: center;\n    justify-content: flex-end;\n    gap: 5px;\n    min-width: max-content;\n    margin: 0;\n  }\n\n  .nav-login,\n  .nav-register {\n    flex: 0 0 auto;\n    min-width: 0;\n    min-height: 32px;\n    height: 32px;\n    padding: 0 10px;\n    margin: 0;\n    border-radius: 10px;\n    font-size: 9px;\n    line-height: 1;\n    white-space: nowrap;\n    box-shadow: none;\n  }\n\n  .nav-register {\n    padding-inline: 11px;\n    box-shadow: 0 5px 14px rgba(255,111,20,.22);\n  }\n\n  .menu-toggle {\n    display: grid !important;\n    flex: 0 0 36px;\n    width: 36px;\n    height: 36px;\n    margin: 0 0 0 1px !important;\n    padding: 0;\n    place-items: center;\n    justify-self: auto;\n    border-radius: 50%;\n    font-size: 16px;\n    line-height: 1;\n  }\n\n  main { padding-top: 66px; }\n\n  .nav-wrap #mainNav {\n    top: 61px;\n    left: 10px;\n    right: 10px;\n  }\n}\n\n@media (max-width: 430px) {\n  .nav-wrap {\n    padding-inline: 9px;\n    gap: 5px;\n  }\n\n  .nav-wrap .brand-logo {\n    width: clamp(104px, 29vw, 124px);\n  }\n\n  .nav-actions { gap: 4px; }\n\n  .nav-login,\n  .nav-register {\n    height: 30px;\n    min-height: 30px;\n    padding-inline: 8px;\n    border-radius: 9px;\n    font-size: 8px;\n  }\n\n  .nav-register { padding-inline: 9px; }\n  .menu-toggle { flex-basis: 34px; width: 34px; height: 34px; font-size: 15px; }\n}\n\n@media (max-width: 370px) {\n  .nav-wrap {\n    padding-inline: 8px;\n    gap: 4px;\n  }\n\n  .nav-wrap .brand-logo { width: 102px; }\n\n  .nav-login,\n  .nav-register {\n    height: 28px;\n    min-height: 28px;\n    padding-inline: 6px;\n    font-size: 7.3px;\n  }\n\n  .nav-register { padding-inline: 7px; }\n  .menu-toggle { flex-basis: 32px; width: 32px; height: 32px; }\n}\n\n/* ===== v42 final responsive layout cleanup ===== */\n@media (min-width: 761px) {\n  .nav-wrap,\n  .hero,\n  .games-section .page-shell,\n  .benefits,\n  .agent-activity .page-shell,\n  .support-section,\n  .platform-details-inner,\n  footer .page-shell { width: min(1240px, calc(100% - 48px)); }\n  .nav-wrap { margin-top: 18px; }\n  .hero-grid {\n    width: min(1180px, calc(100% - 64px));\n    min-height: 650px;\n    grid-template-columns: minmax(0, 1fr) minmax(420px, .92fr);\n    gap: 28px;\n  }\n  .hero-copy { padding: 54px 0 32px; }\n  .hero-art { min-height: 650px; }\n  .hero-art > img { inset: auto 0 0 auto; width: 112%; height: 100%; object-fit: contain; object-position: center bottom; }\n  .games-section { padding: 58px 0 54px; }\n  .games-heading { margin-bottom: 28px; }\n  .benefits { margin-top: 24px; }\n  .agent-activity { margin-top: 34px; padding: 64px 0 66px; }\n  .activity-heading { margin-bottom: 34px; }\n  .support-section { padding: 70px 0; gap: 60px; }\n  .platform-details { padding: 42px 24px 34px; }\n}\n\n@media (max-width: 760px) {\n  .hero-grid {\n    width: 100%; padding: 0 12px 18px; display: grid;\n    grid-template-columns: minmax(0, 1fr);\n    grid-template-areas: "intro" "verify" "access" "actions" "stats" "art";\n    gap: 0;\n  }\n  .hero-intro { padding: 24px 6px 16px; }\n  .hero h1 { font-size: clamp(42px, 13vw, 58px); letter-spacing: -3.4px; }\n  .hero-lead { max-width: 520px; font-size: 10px; }\n  .hero-art {\n    grid-area: art; width: 100%; min-height: 330px; margin-top: 18px;\n    border: 1px solid rgba(76,111,153,.82); border-radius: 16px; overflow: hidden;\n    background: linear-gradient(145deg,#162b48,#0b1424 72%);\n  }\n  .hero-art::before { inset: 10px 8px; border-radius: 14px; }\n  .hero-art::after { top: 18px; right: 16px; width: 40px; height: 40px; }\n  .hero-art > img { inset: auto 0 0 0; width: 100%; height: 100%; max-width: none; object-fit: contain; object-position: center bottom; }\n  .hero-stats { margin-top: 12px; }\n  .games-section { padding: 30px 0 28px; }\n  .benefits { margin-top: 12px; }\n  .agent-activity { margin-top: 18px; padding: 34px 0 38px; }\n  .support-section { padding: 40px 0 44px; }\n  .platform-details { padding-top: 30px; padding-bottom: 28px; }\n}\n\n@media (max-width: 430px) {\n  .hero-art { min-height: 290px; margin-top: 16px; }\n  .hero h1 { font-size: clamp(40px, 12.6vw, 52px); }\n}\n\n/* ===== v43 mobile mascot artwork replacement =====\n   Uses the supplied orange Maanwin raccoon artwork only for the standalone\n   mascot card on phone. Desktop hero artwork and all functional logic stay unchanged. */\n@media (max-width: 760px) {\n  .hero-art {\n    width: 100%;\n    min-height: 0;\n    aspect-ratio: 344 / 403;\n    margin-top: 16px;\n    border: 1px solid rgba(76,111,153,.82);\n    border-radius: 16px;\n    overflow: hidden;\n    background: #0b1424;\n    box-shadow: 0 12px 28px rgba(0,0,0,.18);\n  }\n\n  .hero-art-visual {\n    position: absolute;\n    inset: 0;\n    display: block;\n  }\n  .hero-art-visual img {\n    display: block;\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n  }\n\n  /* The replacement artwork already contains its own coins, glow and mascot. */\n  .hero-art::before,\n  .hero-art::after,\n  .hero-art > img,\n  .hero-art-logo,\n  .jackpot-card {\n    display: none !important;\n  }\n}\n\n@media (max-width: 430px) {\n  .hero-art {\n    min-height: 0;\n    aspect-ratio: 344 / 403;\n    margin-top: 14px;\n  }\n}\n\n/* ===== v46 desktop hero: responsive transparent mascot image ===== */\n@media (min-width: 761px) {\n  .hero {\n    background:\n      radial-gradient(circle at 77% 46%, rgba(246,112,21,.18), transparent 33%),\n      linear-gradient(135deg,#080d16 0%,#0d1625 54%,#070b12 100%);\n  }\n  .hero-grid {\n    min-height: 0;\n    grid-template-columns: minmax(0,1.08fr) minmax(0,.92fr);\n    gap: clamp(26px,3.5vw,54px);\n    align-items: center;\n  }\n  .hero-copy { min-width: 0; padding: 52px 0 46px; }\n  .hero h1 { font-size: clamp(66px,6.5vw,96px); }\n  .hero-verify { margin-top: 25px; }\n  .hero-art {\n    min-width: 0;\n    min-height: 640px;\n    align-self: stretch;\n    overflow: hidden;\n  }\n  .hero-art::before {\n    inset: 12% 1%;\n    z-index: 0;\n    border-radius: 50%;\n    background: radial-gradient(circle,rgba(255,138,33,.3),rgba(255,116,22,.08) 55%,transparent 73%);\n  }\n  .hero-art::after { display: none; }\n  .hero-art-visual {\n    position: absolute;\n    inset: 0;\n    z-index: 1;\n    display: flex;\n    align-items: flex-end;\n    justify-content: center;\n  }\n  .hero-art-visual img {\n    display: block;\n    flex: none;\n    width: 118%;\n    height: 100%;\n    max-width: none;\n    object-fit: contain;\n    object-position: center bottom;\n    filter: drop-shadow(0 24px 30px rgba(0,0,0,.34));\n  }\n  .hero-ring,\n  .hero-art-logo,\n  .jackpot-card { display: none; }\n}\n\n@media (min-width: 761px) and (max-width: 1080px) {\n  .hero-grid { grid-template-columns: minmax(0,1fr); gap: 0; }\n  .hero-copy { padding-bottom: 18px; }\n  .hero-art { width: min(100%,620px); min-height: 500px; margin: 0 auto; }\n  .hero-art-visual img { width: 100%; }\n}\n\n/* ===== v47 compact carousel and section spacing ===== */\n.game-window {\n  width: 100%;\n  overflow: hidden;\n  padding: 7px 0 9px;\n}\n\n@media (min-width: 761px) {\n  .games-section { padding: 32px 0 20px; }\n  .games-heading { margin-bottom: 16px; }\n  .games-heading h2 { font-size: clamp(42px,4.2vw,58px); letter-spacing: -3.5px; }\n  .game-grid { --game-gap: 12px; }\n  .game-card { flex-basis: 154px; padding: 5px; border-radius: 10px; }\n  .game-image { border-radius: 7px; }\n  .game-image > span { top: 7px; left: 7px; min-width: 25px; padding: 5px 6px; }\n  .game-image > b { right: 8px; bottom: 8px; width: 30px; height: 30px; }\n\n  .benefits { margin-top: 8px; }\n  .agent-activity { margin-top: 0; padding: 28px 0 26px; }\n  .activity-heading { margin-bottom: 26px; }\n  .support-section { padding: 26px 0 22px; }\n  .platform-details { padding: 18px 24px 26px; }\n}\n\n@media (max-width: 760px) {\n  .game-window { padding: 4px 0 7px; }\n}\n\n/* ===== v48 desktop hero inspired by the supplied reference ===== */\n@media (min-width: 761px) {\n  .hero-trust {\n    width: min(700px,100%);\n    min-height: 48px;\n    margin-top: 20px;\n    padding: 0 6px;\n    display: flex;\n    align-items: center;\n    border: 1px solid #47617e;\n    border-radius: 16px;\n    background: rgba(9,19,33,.8);\n  }\n  .hero-trust span {\n    min-width: 0;\n    flex: 1;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    gap: 9px;\n    padding: 6px 10px;\n    color: #f6f8fc;\n    font-size: 11px;\n    font-weight: 750;\n    white-space: nowrap;\n  }\n  .hero-trust span + span { border-left: 1px solid #405674; }\n  .hero-trust b { color: #ff9b20; font-size: 21px; line-height: 1; }\n\n  .hero-art::before {\n    inset: 7% -8% 0;\n    background: radial-gradient(circle at 54% 47%,rgba(255,121,19,.35),rgba(255,112,12,.1) 46%,transparent 71%);\n  }\n  .hero-orbit {\n    position: absolute;\n    inset: 12% 0 7%;\n    z-index: 0;\n    border: 1px solid rgba(255,135,24,.24);\n    border-radius: 50%;\n    box-shadow: 0 0 0 38px rgba(255,137,26,.035),0 0 90px rgba(255,105,13,.18);\n  }\n  .hero-coin {\n    position: absolute;\n    top: 11%;\n    left: 14%;\n    z-index: 2;\n    width: 66px;\n    height: 66px;\n    display: grid;\n    place-items: center;\n    border: 5px solid #ffc05b;\n    border-radius: 50%;\n    background: linear-gradient(145deg,#ffcb48,#ff7a08);\n    box-shadow: 0 0 0 4px rgba(255,128,13,.22),0 12px 34px rgba(255,112,9,.4);\n    color: #9c4100;\n    font-size: 35px;\n    font-weight: 900;\n    transform: rotate(-16deg);\n  }\n  .hero-gem {\n    position: absolute;\n    z-index: 2;\n    width: 44px;\n    height: 44px;\n    clip-path: polygon(50% 0,90% 22%,100% 68%,50% 100%,0 68%,10% 22%);\n    background: linear-gradient(135deg,#ffe067 0%,#ff8a09 48%,#aa3f00 100%);\n    box-shadow: 0 0 24px rgba(255,128,12,.4);\n    opacity: .9;\n  }\n  .hero-gem-one { top: 26%; left: 4%; transform: rotate(18deg); }\n  .hero-gem-two { top: 39%; right: 4%; width: 30px; height: 30px; background: linear-gradient(135deg,#a6e8ff,#4284a8 55%,#244663); }\n  .hero-access-badge {\n    position: absolute;\n    top: 52px;\n    right: 3%;\n    z-index: 3;\n    min-width: 235px;\n    min-height: 70px;\n    padding: 12px 16px;\n    display: flex;\n    align-items: center;\n    gap: 13px;\n    border: 1px solid #ef8217;\n    border-radius: 15px;\n    background: rgba(15,18,27,.91);\n    box-shadow: 0 0 25px rgba(255,113,15,.22);\n    transform: rotate(3deg);\n  }\n  .hero-access-badge > span {\n    width: 44px;\n    height: 44px;\n    flex: none;\n    display: grid;\n    place-items: center;\n    border: 3px solid #ffc358;\n    border-radius: 12px;\n    color: #ffc358;\n    font-size: 27px;\n    font-weight: 900;\n  }\n  .hero-access-badge strong,\n  .hero-access-badge small { display: block; text-transform: uppercase; }\n  .hero-access-badge strong { color: #fff; font-size: 16px; line-height: 1.1; }\n  .hero-access-badge small { margin-top: 3px; color: #ffae32; font-size: 10px; letter-spacing: .9px; }\n  .hero-move-card {\n    position: absolute;\n    right: 10px;\n    bottom: 28px;\n    z-index: 4;\n    width: min(440px,82%);\n    min-height: 92px;\n    padding: 15px 16px 15px 24px;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 12px;\n    border: 1px solid #ef8217;\n    border-radius: 18px;\n    background: rgba(11,20,34,.96);\n    box-shadow: 0 18px 40px rgba(0,0,0,.34),0 0 30px rgba(255,109,16,.15);\n    color: #fff;\n  }\n  .hero-move-card > span { color: #ffc055; font-size: 10px; font-weight: 850; letter-spacing: 1.7px; text-transform: uppercase; }\n  .hero-move-card strong { display: block; margin-top: 7px; color: #fff; font-size: 21px; line-height: 1; letter-spacing: -.7px; }\n  .hero-move-card b { width: 52px; height: 52px; flex: none; display: grid; place-items: center; border-radius: 50%; background: var(--orange-gradient); color: #fff; font-size: 30px; font-weight: 400; }\n  .hero-move-card:hover { border-color: #ffbf60; transform: translateY(-2px); }\n}\n\n@media (min-width: 1081px) {\n  .nav-wrap,\n  .hero { width: min(1600px,calc(100% - 24px)); }\n  .nav-wrap { height: 88px; padding-inline: clamp(28px,3vw,56px); }\n  .hero {\n    margin-top: 0;\n    border-top: 0;\n    border-radius: 0 0 24px 24px;\n    background: radial-gradient(circle at 80% 50%,rgba(190,75,9,.29),transparent 34%),linear-gradient(110deg,#06101d 0%,#081322 48%,#111826 100%);\n  }\n  .hero-grid {\n    width: min(1480px,calc(100% - 88px));\n    min-height: 810px;\n    grid-template-columns: minmax(0,1fr) minmax(0,1fr);\n    gap: 14px;\n  }\n  .hero-copy { padding: 48px 0 42px; }\n  .hero h1 { margin: 20px 0 18px; font-size: clamp(80px,7.3vw,118px); line-height: .81; letter-spacing: -7px; }\n  .hero-lead { max-width: 660px; font-size: 16px; line-height: 1.56; }\n  .hero-verify {\n    width: min(700px,100%);\n    margin-top: 14px;\n    padding: 14px;\n    grid-template-columns: 62px minmax(0,1fr) 150px;\n    grid-template-rows: auto 50px;\n    gap: 8px 12px;\n    border-radius: 18px;\n  }\n  .hero-verify .verify-intro { grid-column: 1 / -1; }\n  .hero-verify .shield { width: 58px; height: 58px; font-size: 28px; }\n  .hero-verify .verify-intro strong { font-size: 15px; }\n  .hero-verify .verify-intro small { font-size: 11px; }\n  .hero-verify label { grid-column: 2; grid-row: 2; height: 50px; }\n  .hero-verify > button { grid-column: 3; grid-row: 2; height: 50px; min-width: 0; font-size: 12px; }\n  .hero-access-panel { width: min(700px,100%); margin-top: 0; }\n  .hero-access-panel .route-grid > a { min-height: 53px; }\n  .hero-access-panel .route-grid strong { font-size: 12px; }\n  .hero-actions { margin-top: 20px; }\n  .hero .primary-button { min-height: 60px; min-width: 240px; font-size: 13px; }\n  .hero-stats { max-width: 700px; margin-top: 20px; gap: 12px; }\n  .hero-stats div { min-height: 84px; }\n  .hero-stats strong { font-size: 24px; }\n  .hero-art { min-height: 810px; }\n  .hero-art-visual img { width: 125%; }\n}\n\n@media (min-width: 761px) and (max-width: 1080px) {\n  .hero-trust span { font-size: 10px; gap: 6px; }\n  .hero-access-badge { top: 24px; right: 4%; transform: rotate(2deg) scale(.86); transform-origin: top right; }\n  .hero-move-card { bottom: 12px; right: 4%; transform: scale(.9); transform-origin: bottom right; }\n  .hero-coin { top: 7%; left: 11%; transform: rotate(-16deg) scale(.8); }\n}\n\n@media (max-width: 760px) {\n  .hero-trust,\n  .hero-orbit,\n  .hero-coin,\n  .hero-gem,\n  .hero-access-badge,\n  .hero-move-card { display: none; }\n}\n\n/* ===== v49: richer desktop scene and reference-sized hero details ===== */\n.stat-icon svg {\n  width: 17px;\n  height: 17px;\n  fill: none;\n  stroke: currentColor;\n  stroke-width: 2.1;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n}\n\n@media (min-width: 761px) {\n  .hero {\n    background:\n      linear-gradient(90deg,rgba(4,13,25,.92) 0%,rgba(4,13,25,.72) 33%,rgba(4,13,25,.16) 63%,rgba(4,13,25,.05) 100%),\n      url("../images/maanwin-hero-scene-v2.webp") center 43% / cover no-repeat,\n      #071322;\n  }\n  .hero-trust { min-height: 53px; border-radius: 17px; }\n  .hero-trust span { gap: 11px; font-size: 13px; }\n  .hero-trust svg {\n    width: 23px;\n    height: 23px;\n    flex: none;\n    fill: none;\n    stroke: #ff9c20;\n    stroke-width: 2.3;\n    stroke-linecap: round;\n    stroke-linejoin: round;\n  }\n  .hero-trust span:nth-child(2) svg { fill: #ff9c20; stroke-width: 1.2; }\n  .hero-art::before,\n  .hero-orbit { display: none; }\n  .hero-access-badge {\n    top: 66px;\n    right: 1%;\n    min-width: clamp(260px,24vw,355px);\n    min-height: 92px;\n    padding: 15px 20px;\n    gap: 16px;\n    border-radius: 18px;\n    box-shadow: 0 12px 32px rgba(0,0,0,.43),0 0 28px rgba(255,123,18,.24);\n  }\n  .hero-access-badge > span { width: 57px; height: 57px; border: 0; border-radius: 0; }\n  .hero-access-badge svg {\n    width: 57px;\n    height: 57px;\n    fill: rgba(255,145,27,.14);\n    stroke: #ffad32;\n    stroke-width: 1.8;\n    stroke-linecap: round;\n    stroke-linejoin: round;\n    filter: drop-shadow(0 0 8px rgba(255,143,21,.4));\n  }\n  .hero-access-badge strong { font-size: clamp(17px,1.6vw,22px); }\n  .hero-access-badge small { font-size: 12px; letter-spacing: 1.1px; }\n  .hero-move-card { width: min(480px,86%); min-height: 105px; padding: 17px 20px 17px 26px; }\n  .hero-move-card > span { font-size: 12px; }\n  .hero-move-card strong { font-size: 24px; }\n  .hero-move-card b { width: 60px; height: 60px; font-size: 34px; }\n  .hero-stats div {\n    min-height: 94px;\n    grid-template-columns: 42px auto;\n    column-gap: 12px;\n    padding: 13px 15px;\n  }\n  .stat-icon { width: 42px; height: 42px; background: transparent; border-radius: 0; }\n  .stat-icon svg { width: 33px; height: 33px; stroke: #ff9c20; stroke-width: 2.5; }\n  .hero-stats strong { font-size: 27px; }\n  .hero-stats small { font-size: 9px; letter-spacing: .8px; }\n}\n\n@media (min-width: 1081px) {\n  .hero-art-visual img { width: 140%; }\n}\n\n@media (min-width: 761px) and (max-width: 1080px) {\n  .hero {\n    background:\n      linear-gradient(180deg,rgba(4,13,25,.78),rgba(4,13,25,.2)),\n      url("../images/maanwin-hero-scene-v2.webp") center / cover no-repeat,\n      #071322;\n  }\n  .hero-trust span { font-size: 11px; gap: 6px; }\n  .hero-trust svg { width: 19px; height: 19px; }\n  .hero-access-badge { top: 30px; right: 4%; min-width: 260px; transform: rotate(2deg) scale(.86); }\n  .hero-move-card { bottom: 12px; right: 4%; transform: scale(.9); }\n  .hero-stats div { min-height: 78px; grid-template-columns: 32px auto; padding: 10px; }\n  .stat-icon { width: 32px; height: 32px; }\n  .stat-icon svg { width: 26px; height: 26px; }\n  .hero-stats strong { font-size: 20px; }\n  .hero-stats small { font-size: 7px; }\n}\n\n/* ===== v50: wider PC layout and raised phone detail ===== */\n@media (min-width: 761px) {\n  .hero-art { overflow: visible; }\n  .hero-phone-pop {\n    position: absolute;\n    inset: 0;\n    z-index: 2;\n    display: flex;\n    align-items: flex-end;\n    justify-content: center;\n    pointer-events: none;\n    transform: translate(-9px,-11px);\n    filter: drop-shadow(-8px 16px 12px rgba(0,0,0,.58)) drop-shadow(0 0 11px rgba(255,124,24,.32));\n  }\n  .hero-phone-pop img {\n    display: block;\n    flex: none;\n    width: 118%;\n    height: 100%;\n    max-width: none;\n    object-fit: contain;\n    object-position: center bottom;\n    clip-path: polygon(9% 37%,36% 36%,43% 75%,39% 87%,12% 92%,6% 70%);\n    -webkit-mask-image: radial-gradient(ellipse 23% 38% at 26% 63%,#000 58%,transparent 86%);\n    mask-image: radial-gradient(ellipse 23% 38% at 26% 63%,#000 58%,transparent 86%);\n  }\n}\n\n@media (min-width: 1081px) {\n  .hero-phone-pop img { width: 140%; }\n  .games-section .page-shell { width: min(1840px,calc(100% - 36px)); }\n  .games-heading { padding-inline: clamp(24px,3vw,70px); }\n}\n\n@media (min-width: 1601px) {\n  .nav-wrap,\n  .hero { width: min(1840px,calc(100% - 36px)); }\n  .hero-grid {\n    width: min(1700px,calc(100% - 104px));\n    grid-template-columns: minmax(0,.88fr) minmax(0,1.12fr);\n    gap: 14px;\n  }\n  .benefits,\n  .agent-activity .page-shell,\n  .support-section,\n  .platform-details-inner,\n  footer .page-shell { width: min(1700px,calc(100% - 104px)); }\n}\n\n@media (min-width: 761px) and (max-width: 1080px) {\n  .hero-phone-pop img { width: 100%; }\n}\n\n@media (max-width: 760px) {\n  .hero-phone-pop { display: none; }\n}\n\n/* ===== v51: keep desktop navigation close to the account actions ===== */\n@media (min-width: 1081px) {\n  .nav-wrap nav { margin: 0 clamp(24px,3vw,56px) 0 auto; }\n}\n\n/* ===== v52: compact horizontal hero banner on phones ===== */\n.hero-mobile-play { display: none; }\n\n@media (max-width: 760px) {\n  .hero-art {\n    width: 100%;\n    min-height: 0;\n    aspect-ratio: 1000 / 454;\n    margin-top: 14px;\n    border-radius: 14px;\n    box-shadow: 0 12px 25px rgba(0,0,0,.28);\n  }\n  .hero-art-visual img { object-fit: cover; }\n  .hero-move-card {\n    position: absolute;\n    inset: 0;\n    z-index: 4;\n    width: 100%;\n    height: 100%;\n    min-height: 0;\n    padding: 14px 16px;\n    display: flex;\n    align-items: center;\n    border: 0;\n    border-radius: inherit;\n    background: linear-gradient(90deg,rgba(4,12,25,.58),rgba(4,12,25,.18) 55%,transparent 76%);\n    box-shadow: none;\n    color: #fff;\n    text-decoration: none;\n  }\n  .hero-move-card > span {\n    display: block;\n    width: 52%;\n    color: #ffb53e;\n    font-size: 8px;\n    font-weight: 850;\n    letter-spacing: 1.1px;\n    line-height: 1.2;\n    text-transform: uppercase;\n    text-shadow: 0 2px 8px rgba(0,0,0,.72);\n  }\n  .hero-move-card strong {\n    display: block;\n    margin-top: 5px;\n    color: #fff;\n    font-size: clamp(17px,5.6vw,22px);\n    line-height: 1;\n    letter-spacing: -.5px;\n  }\n  .hero-mobile-play {\n    width: max-content;\n    min-height: 25px;\n    margin-top: 10px;\n    padding: 0 10px;\n    display: inline-flex;\n    align-items: center;\n    border: 1px solid rgba(255,193,91,.7);\n    border-radius: 7px;\n    background: linear-gradient(180deg,#ffa629,#ff7917);\n    box-shadow: 0 6px 14px rgba(255,104,14,.25);\n    color: #fff;\n    font-size: 8px;\n    font-weight: 900;\n    letter-spacing: .6px;\n  }\n  .hero-move-card b { display: none; }\n}\n\n/* ===== v53: merge Start Playing + Explore Games into one compact CTA ===== */\n.hero-actions {\n  width: min(700px,100%);\n  display: block;\n  margin-top: 16px;\n}\n.hero-action-bar {\n  width: 100%;\n  min-height: 58px;\n  display: flex;\n  align-items: stretch;\n  overflow: hidden;\n  border: 1px solid rgba(255,185,70,.52);\n  border-radius: 13px;\n  background: linear-gradient(180deg,#ffae31 0%,#ff8418 48%,#ff6d10 100%);\n  box-shadow: 0 10px 24px rgba(255,104,15,.22), inset 0 1px 0 rgba(255,255,255,.28);\n}\n.hero-action-start.primary-button {\n  flex: 1.08;\n  min-width: 0;\n  min-height: 58px;\n  padding: 0 18px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 11px;\n  border: 0;\n  border-radius: 0;\n  background: transparent;\n  box-shadow: none;\n  color: #fff;\n  font-size: 12px;\n  font-weight: 900;\n  letter-spacing: .35px;\n  text-transform: uppercase;\n  white-space: nowrap;\n}\n.hero-action-start.primary-button:hover {\n  background: rgba(255,255,255,.08);\n  color: #fff;\n  transform: none;\n}\n.hero-action-start strong { font: inherit; }\n.hero-action-play {\n  width: 30px;\n  height: 30px;\n  flex: none;\n  display: grid;\n  place-items: center;\n  padding-left: 2px;\n  border: 1px solid rgba(255,255,255,.38);\n  border-radius: 50%;\n  background: rgba(15,27,45,.74);\n  color: #ffae2b;\n  font-size: 10px;\n}\n.hero-action-divider {\n  width: 1px;\n  height: 30px;\n  align-self: center;\n  flex: none;\n  background: rgba(255,255,255,.48);\n}\n.hero-action-explore {\n  flex: .92;\n  min-width: 0;\n  min-height: 58px;\n  padding: 0 18px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 10px;\n  color: #fff;\n  font-size: 11px;\n  font-weight: 850;\n  letter-spacing: .15px;\n  white-space: nowrap;\n  transition: background .2s ease;\n}\n.hero-action-explore:hover { background: rgba(255,255,255,.08); }\n.hero-action-explore svg {\n  width: 20px;\n  height: 20px;\n  flex: none;\n  fill: none;\n  stroke: currentColor;\n  stroke-width: 1.9;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n}\n.hero-action-explore b {\n  font-size: 18px;\n  line-height: 1;\n  font-weight: 500;\n}\n.hero-stats { margin-top: 12px; }\n\n@media (min-width: 1081px) {\n  .hero-actions { margin-top: 16px; }\n  .hero-action-bar { min-height: 58px; }\n  .hero-action-start.primary-button,\n  .hero-action-explore { min-height: 58px; }\n  .hero-stats { margin-top: 14px; }\n}\n\n@media (max-width: 760px) {\n  .hero-actions {\n    width: 100%;\n    margin-top: 11px;\n  }\n  .hero-action-bar {\n    min-height: 47px;\n    border-radius: 10px;\n  }\n  .hero-action-start.primary-button {\n    flex: 1.08;\n    min-height: 47px;\n    padding: 0 10px;\n    gap: 7px;\n    font-size: 8.2px;\n    letter-spacing: .22px;\n  }\n  .hero-action-play {\n    width: 25px;\n    height: 25px;\n    font-size: 8px;\n  }\n  .hero-action-divider { height: 25px; }\n  .hero-action-explore {\n    flex: .92;\n    min-height: 47px;\n    padding: 0 9px;\n    gap: 6px;\n    font-size: 8px;\n  }\n  .hero-action-explore svg { width: 17px; height: 17px; }\n  .hero-action-explore b { font-size: 15px; }\n  .hero-stats { margin-top: 10px; }\n}\n\n@media (max-width: 390px) {\n  .hero-action-start.primary-button { padding-inline: 8px; font-size: 7.6px; }\n  .hero-action-explore { padding-inline: 7px; font-size: 7.5px; }\n  .hero-action-start.primary-button,\n  .hero-action-explore { gap: 5px; }\n}\n\n/* ===== v43 requested mobile clarity + responsible-play alignment ===== */\n.platform-responsible {\n  display: flex;\n  align-items: center;\n  gap: 20px;\n  margin: 17px 0 22px;\n}\n.platform-responsible .platform-warning {\n  flex: 1 1 auto;\n  min-width: 0;\n  margin: 0;\n}\n.platform-responsible .platform-age {\n  flex: 0 0 auto;\n}\n\n@media (max-width: 760px) {\n  /* Make the small orange eyebrow text easier to read on phones. */\n  .hero .kicker {\n    gap: 7px;\n    font-size: 8.2px;\n    line-height: 1.2;\n    font-weight: 900;\n    letter-spacing: 1.05px;\n    white-space: nowrap;\n    color: #ff981f;\n    text-shadow: 0 1px 8px rgba(255,126,20,.28);\n  }\n  .hero .kicker i {\n    width: 22px;\n    height: 2px;\n    border-radius: 999px;\n    background: #ff981f;\n    box-shadow: 0 0 8px rgba(255,126,20,.22);\n  }\n\n  /* Keep 18+ beside the responsible-play notice instead of on a new row. */\n  .platform-responsible {\n    width: 100%;\n    display: grid;\n    grid-template-columns: minmax(0,1fr) auto;\n    align-items: center;\n    gap: 12px;\n    margin: 14px 0 18px;\n  }\n  .platform-responsible .platform-warning {\n    margin: 0;\n    padding-right: 12px;\n    border-right: 1px solid rgba(255,255,255,.18);\n    font-size: 10.5px;\n    line-height: 1.45;\n  }\n  .platform-responsible .platform-age {\n    width: 48px;\n    height: 48px;\n    font-size: 15px;\n    border-width: 2px;\n  }\n}\n\n@media (max-width: 380px) {\n  .hero .kicker {\n    gap: 6px;\n    font-size: 7.4px;\n    letter-spacing: .78px;\n  }\n  .hero .kicker i { width: 18px; }\n  .platform-responsible { gap: 9px; }\n  .platform-responsible .platform-warning {\n    padding-right: 9px;\n    font-size: 9.4px;\n  }\n  .platform-responsible .platform-age {\n    width: 44px;\n    height: 44px;\n    font-size: 14px;\n  }\n}\n',108036,'text/plain');
