INSERT INTO `cloned_files` (`path`,`content`,`size`,`mime`) VALUES ('index.html','<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <meta name="description" content="Maanwin is a trusted and popular gaming platform for players across India.">\n  <meta property="og:title" content="Maanwin &mdash; Trusted Platform">\n  <meta property="og:description" content="One of India\'s most popular gaming platforms with verified access routes.">\n  <meta property="og:image" content="images/og.jpg">\n  <title>MAAN.WIN &mdash; INDIAN PLATFORM</title>\n  <link rel="icon" type="image/webp" sizes="192x192" href="images/favicon-192_5e1f15.png">\n  <link rel="shortcut icon" type="image/webp" href="images/favicon-192_5e1f15.png">\n  <link rel="apple-touch-icon" href="images/favicon-192_5e1f15.png">\n  <link rel="stylesheet" href="css/styles_502b90.css">\n</head>\n<body>\n  <header class="nav-wrap">\n    <a class="brand" href="#top" aria-label="Maanwin home"><img class="brand-logo" src="images/maanwin-logo-wordmark.webp" alt="Maanwin" width="500" height="102"></a>\n    <button id="menuButton" class="menu-toggle" aria-label="Toggle navigation" aria-expanded="false">&#9776;</button>\n    <nav id="mainNav">\n      <a href="#top">Home</a>\n      <a href="#games">Games</a>\n      <a href="#agent-activity">Promotions</a>\n      <a href="#support">VIP</a>\n      <a href="#providers">Help</a>\n    </nav>\n    <div class="nav-actions">\n    </div>\n  </header>\n\n  <main>\n    <section class="hero" id="top">\n      <div class="hero-grid">\n        <div class="hero-copy">\n          <div class="hero-intro">\n            <p class="kicker"><i></i> India\'s most popular gaming platform</p>\n            <h1>Trusted<br><em>platform.</em></h1>\n            <p class="hero-lead">Maan.Win is a trusted platform for players across India, bringing popular games, verified access routes, and smooth play to every device.</p>\n          </div>\n          <div class="hero-trust" aria-label="Platform highlights">\n            <span><svg viewbox="0 0 24 24" aria-hidden="true"><path d="M12 2 3.5 5.5v6.1c0 5 3.5 8.8 8.5 10.4 5-1.6 8.5-5.4 8.5-10.4V5.5L12 2Z"></path><path d="m8 11.8 2.5 2.5 5.5-5.6"></path></svg>Official Domains</span>\n            <span><svg viewbox="0 0 24 24" aria-hidden="true"><path d="m13.5 2-9 11h6l-1 9 10-12h-6l1-8Z"></path></svg>Secure Access</span>\n            <span><svg viewbox="0 0 24 24" aria-hidden="true"><path d="M2.5 8a15.6 15.6 0 0 1 19 0M5.7 11.8a10.6 10.6 0 0 1 12.6 0M9.1 15.5a5.5 5.5 0 0 1 5.8 0"></path><circle cx="12" cy="19" r="1.4"></circle></svg>Fast Connection</span>\n          </div>\n          <form id="verifyForm" class="verify-box hero-verify">\n            <div class="verify-intro"><span class="shield">&#10003;</span><span><strong>Check a domain</strong><small>Verify before you sign in</small></span></div>\n            <label><span>&#8981;</span><input id="domainInput" placeholder="Enter a domain name" aria-label="Domain to verify"></label>\n            <button type="submit">Verify <span>&rarr;</span></button>\n            <div id="verifyMessage" class="verify-message" role="status" aria-live="polite" hidden></div>\n          </form>\n          <div class="access-panel hero-access-panel" id="access">\n            <div id="routeGrid" class="route-grid"></div>\n          </div>\n          <div class="hero-actions">\n            <div class="hero-action-bar" role="group" aria-label="Game actions">\n              <a class="primary-button main-link hero-action-start" href="https://maanwin1.com" target="_blank" rel="noreferrer">\n                <span class="hero-action-play" aria-hidden="true">&#9654;</span>\n                <strong>Start Playing</strong>\n              </a>\n              <span class="hero-action-divider" aria-hidden="true"></span>\n              <a class="hero-action-explore" href="#games">\n                <svg viewbox="0 0 24 24" aria-hidden="true"><path d="M6.5 8h11a3 3 0 0 1 2.9 2.3l1.3 5.5a2.5 2.5 0 0 1-4.1 2.5l-2.7-2.5H9.1l-2.7 2.5a2.5 2.5 0 0 1-4.1-2.5l1.3-5.5A3 3 0 0 1 6.5 8Z"></path><path d="M7.5 10.8v4.2m-2.1-2.1h4.2"></path><circle cx="16.6" cy="11.8" r=".8"></circle><circle cx="18.5" cy="14" r=".8"></circle></svg>\n                <span>Explore games</span>\n                <b aria-hidden="true">&rarr;</b>\n              </a>\n            </div>\n          </div>\n          <div class="hero-stats">\n            <div><span class="stat-icon" aria-hidden="true"><svg viewbox="0 0 24 24"><path d="M12 2 3.5 5.5v6.1c0 5 3.5 8.8 8.5 10.4 5-1.6 8.5-5.4 8.5-10.4V5.5L12 2Z"></path><path d="m8 11.8 2.5 2.5 5.5-5.6"></path></svg></span><strong>24/7</strong><small>platform access</small></div>\n            <div><span class="stat-icon stat-game" aria-hidden="true"><svg viewbox="0 0 24 24"><path d="M6.5 8h11a3 3 0 0 1 2.9 2.3l1.3 5.5a2.5 2.5 0 0 1-4.1 2.5l-2.7-2.5H9.1l-2.7 2.5a2.5 2.5 0 0 1-4.1-2.5l1.3-5.5A3 3 0 0 1 6.5 8Z"></path><path d="M7.5 10.8v4.2m-2.1-2.1h4.2"></path><circle cx="16.6" cy="11.8" r=".8"></circle><circle cx="18.5" cy="14" r=".8"></circle></svg></span><strong>19+</strong><small>popular games</small></div>\n            <div><span class="stat-icon stat-users" aria-hidden="true"><svg viewbox="0 0 24 24"><circle cx="12" cy="7" r="3"></circle><path d="M5.5 20v-2.3a4.8 4.8 0 0 1 4.8-4.8h3.4a4.8 4.8 0 0 1 4.8 4.8V20H5.5ZM4.2 7.1a2.4 2.4 0 0 0 0 4.7M19.8 7.1a2.4 2.4 0 0 1 0 4.7"></path></svg></span><strong>18+</strong><small>responsible play</small></div>\n          </div>\n        </div>\n        <div class="hero-art">\n          <div class="hero-orbit" aria-hidden="true"></div>\n          <span class="hero-coin" aria-hidden="true">&#8377;</span>\n          <span class="hero-gem hero-gem-one" aria-hidden="true"></span>\n          <span class="hero-gem hero-gem-two" aria-hidden="true"></span>\n          <picture class="hero-art-visual">\n            <source media="(min-width: 761px)" srcset="images/maanwin-raccoon-cutout.webp" type="image/webp">\n            <img src="images/maanwin-mobile-banner-v1-opt.jpg" alt="Maanwin raccoon mascot holding a phone" width="1000" height="454" decoding="async" fetchpriority="high">\n          </source></picture>\n          <picture class="hero-phone-pop" aria-hidden="true">\n            <source media="(min-width: 761px)" srcset="images/maanwin-raccoon-cutout.webp" type="image/webp">\n            <img src="data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=" alt="" width="1358" height="1159" decoding="async" loading="lazy">\n          </source></picture>\n          <div class="hero-access-badge"><span aria-hidden="true"><svg viewbox="0 0 24 24"><path d="M12 2 3.5 5.5v6.1c0 5 3.5 8.8 8.5 10.4 5-1.6 8.5-5.4 8.5-10.4V5.5L12 2Z"></path><path d="m8 11.8 2.5 2.5 5.5-5.6"></path></svg></span><div><strong>Official access</strong><small>Verified platform</small></div></div>\n          <a class="hero-move-card main-link" href="https://maanwin1.com" target="_blank" rel="noreferrer"><span>Maan.Win select<strong>Your next move.</strong><small class="hero-mobile-play">Play now &#8599;</small></span><b aria-hidden="true">&rarr;</b></a>\n        </div>\n      </div>\n      <div class="ticker">\n        <span>VERIFIED ROUTES</span>\n        <div class="ticker-marquee" aria-label="Fast access, mobile ready, secure platform, responsible play">\n          <div class="ticker-track">\n            <p>FAST ACCESS&nbsp;&nbsp;&#9670;&nbsp;&nbsp; MOBILE READY&nbsp;&nbsp;&#9670;&nbsp;&nbsp; SECURE PLATFORM&nbsp;&nbsp;&#9670;&nbsp;&nbsp; RESPONSIBLE PLAY&nbsp;&nbsp;&#9670;&nbsp;&nbsp;</p>\n            <p aria-hidden="true">FAST ACCESS&nbsp;&nbsp;&#9670;&nbsp;&nbsp; MOBILE READY&nbsp;&nbsp;&#9670;&nbsp;&nbsp; SECURE PLATFORM&nbsp;&nbsp;&#9670;&nbsp;&nbsp; RESPONSIBLE PLAY&nbsp;&nbsp;&#9670;&nbsp;&nbsp;</p>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <section class="games-section" id="games">\n      <div class="page-shell">\n        <div class="games-heading"><div><p class="section-tag">02 / TOP 10 GAMES</p><h2>Pick your next play.</h2></div></div>\n        <div class="game-window"><div id="gameGrid" class="game-grid"></div></div>\n      </div>\n    </section>\n\n    <section class="benefits page-shell">\n      <article><span>01</span><b>Verified entry</b><p>Check every route against the official Maanwin access list.</p></article>\n      <article><span>02</span><b>Made for mobile</b><p>Fast, fluid browsing designed around play on the go.</p></article>\n      <article><span>03</span><b>Always connected</b><p>Multiple active routes keep the platform within easy reach.</p></article>\n    </section>\n\n    <section class="agent-activity" id="agent-activity">\n      <div class="page-shell">\n        <div class="activity-heading">\n          <div><p class="section-tag">03 / AGENT ACTIVITY</p><h2>Grow your network.<br><em>Earn more.</em></h2></div>\n          <p>Share your Maanwin agent link, build an active team, and unlock commission, salary, and invitation bonuses.</p>\n        </div>\n\n        <div class="activity-grid">\n          <article class="activity-card activity-copy-card">\n            <span class="activity-index">A / 01</span>\n            <h3>Why choose Maanwin as an agent?</h3>\n            <p>Agent commission up to <strong>1.4%</strong> &mdash; one of the highest rates on the platform.</p>\n            <p>Use this programme to grow your network and create an additional income stream with a clear reward structure.</p>\n            <a class="telegram-inline telegram-link" href="https://t.me/share/url" target="_blank" rel="noreferrer">\n              <svg viewbox="0 0 24 24" aria-hidden="true"><path d="M21.7 3.5 18.8 20c-.2 1.2-.9 1.5-1.9.9l-4.4-3.3-2.1 2.1c-.2.2-.4.4-.9.4l.3-4.5 8.2-7.4c.4-.3-.1-.5-.5-.2L7.4 14.4 3 13c-1.2-.4-1.2-1.2.2-1.7L20.4 2.7c1-.4 1.8.2 1.3.8Z"></path></svg>\n              Join via Telegram <span>&#8599;</span>\n            </a>\n      